            UssmsCardErrType type = codeMap.get(code);
            if (type == null) {
                throw new IllegalArgumentException("Unknown error code: " + code);
            }
            return type;
        }
    }

    public static String processError(int errorCode) {
        for (UssmsCardErrType err : UssmsCardErrType.values()) {
            if (err.getCode() == errorCode) {
                return "Error " + errorCode + ": " + err.getMessage();
