import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ThreadResourceManager {
    private final ConcurrentHashMap<String, Thread> threadMap;
    private final ScheduledExecutorService monitorService;

    public ThreadResourceManager() {
        threadMap = new ConcurrentHashMap<>();
        monitorService = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            return t;
        });

        // Schedule monitoring task to run every second
        monitorService.scheduleAtFixedRate(this::cleanupDeadThreads, 1, 1, TimeUnit.SECONDS);
    }

    public boolean createDaemonThread(String threadName, Runnable task) {
        if (threadName == null || task == null) {
            return false;
        }

        Thread thread = new Thread(task);
        thread.setName(threadName);
        thread.setDaemon(true);
        thread.start();
        threadMap.put(threadName, thread);
        return true;
    }

    public boolean stopDaemonThread(String threadName) {
        if (threadName == null) {
            return false;
        }

        Thread thread = threadMap.remove(threadName);
        if (thread != null) {
            thread.interrupt();
            return true;
        }
        return false;
    }

    public int getActiveThreadCount() {
        return threadMap.size();
    }

    private void cleanupDeadThreads() {
        threadMap.entrySet().removeIf(entry -> !entry.getValue().isAlive());
    }
}

