    // We'll need to initialize it and manage it
    private java.util.Map<String, List<Note>> categoryNotes;

    public CategoryManager() {
        this.categories = new HashSet<>();
        this.categoryNotes = new java.util.HashMap<>();
        this.currentCategory = "生活";
        this.categories.add(currentCategory);
        this.categoryNotes.put(currentCategory, new ArrayList<>());
    }

    public boolean addCategory(String categoryName) {
        if (categories.contains(categoryName)) {
            return false;
        }
        categories.add(categoryName);
        categoryNotes.put(categoryName, new ArrayList<>());
        return true;
    }

    public List<Note> removeCategory(String categoryName) {
        if (!categories.contains(categoryName)) {
            return null;
        }

        List<Note> removedNotes = categoryNotes.remove(categoryName);
        categories.remove(categoryName);

        if (currentCategory.equals(categoryName)) {
            if (!categories.isEmpty()) {
                currentCategory = categories.iterator().next();
            } else {
                currentCategory = "";
            }
        }

        return removedNotes;
