import java.util.Arrays;
import java.util.Comparator;

public class Venue {
    private int rows;
    private int cols;
    private boolean[][] seats;
    private Integer[] columnOrder;

    public Venue(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.seats = new boolean[rows][cols];
        initializeColumnOrder();
    }

    private void initializeColumnOrder() {
        columnOrder = new Integer[cols];
        for (int i = 0; i < cols; i++) {
            columnOrder[i] = i + 1;
        }

        final double center = (cols + 1) / 2.0;
        Arrays.sort(columnOrder, Comparator
            .comparingDouble((Integer col) -> Math.abs(col - center))
            .thenComparingInt(col -> col));
    }

    public int getNumberOfSeats() {
        return rows * cols;
    }

    public boolean reserveSeat(int row, int col) {
        if (row < 1 || row > rows || col < 1 || col > cols) {
            throw new IllegalArgumentException("Invalid seat coordinates");
        }
        if (seats[row - 1][col - 1]) {
            return false;
        }
        seats[row - 1][col - 1] = true;
        return true;
    }

    public int getAvailableSeats() {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!seats[i][j]) {
                    count++;
                }
            }
        }
        return count;
    }

    public int[] getBestAvailableSeat() {
        for (int row = 1; row <= rows; row++) {
            for (int col : columnOrder) {
                if (!seats[row - 1][col - 1]) {
                    return new int[]{row, col};
                }
            }
        }
        return null;
    }
}

