import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.nio.file.Files;
import java.nio.file.Paths;

public class FileOperationsManager {

    public boolean writeToFile(String filePath, List<String> lines, boolean append) {
        File file = new File(filePath);
        File parentDir = file.getParentFile();

        // Create parent directories if they don't exist
        if (parentDir != null && !parentDir.exists()) {
            try {
                Files.createDirectories(Paths.get(parentDir.getAbsolutePath()));
            } catch (IOException e) {
                return false;
            }
        }

        try (BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(
                        new FileOutputStream(file, append),
                        StandardCharsets.UTF_8
                ))) {
            for (String line : lines) {
                writer.write(line);
                writer.newLine();
            }
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    public List<String> readFromFile(String filePath) {
        List<String> lines = new ArrayList<>();
        File file = new File(filePath);

        if (!file.exists() || !file.isFile()) {
            return lines; // Return empty list if file doesn't exist
        }

        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(
                        new FileInputStream(file),
                        StandardCharsets.UTF_8
                ))) {
            String line;
            while ((line = reader.readLine()) != null) {
                lines.add(line);
            }
        } catch (IOException e) {
            // Return empty list if any error occurs
            return new ArrayList<>();
        }

        return lines;
    }
}

