        try {
            for (int value : writeValues) {
                intBuffer.put(value);
            }
            intBuffer.flip();
            result.append("Initial buffer content: ");
            while (intBuffer.hasRemaining()) {
                result.append(intBuffer.get()).append(" ");
            }
            result.append("\n");

            // Reset buffer for partial read
            intBuffer.rewind();

            // Set position to 1 and limit to 3
            int newPosition = Math.min(1, intBuffer.capacity());
            int newLimit = Math.min(3, intBuffer.capacity());
            if (newPosition > newLimit) {
                newPosition = newLimit;
            }
            intBuffer.position(newPosition);
            intBuffer.limit(newLimit);

            result.append("Partial buffer content (position ")
                  .append(newPosition).append(", limit ")
                  .append(newLimit).append("): ");
            while (intBuffer.hasRemaining()) {
                result.append(intBuffer.get()).append(" ");
            }
            result.append("\n");

