public class ObjectInspector {

    public Map<String, Object> inspectObject(Object obj, int maxDepth) {
        Map<String, Object> result = new HashMap<>();

        if (obj == null) {
            result.put("value", null);
        } else if (obj.getClass().isArray()) {
            if (maxDepth <= 0) {
                result.put("type", getArrayTypeName(obj));
                result.put("value", "max_depth_reached");
            } else {
                result.put("type", getArrayTypeName(obj));
                result.put("value", inspectArrayElements(obj, maxDepth - 1));
            }
        } else if (isSimpleType(obj)) {
            result.put("type", obj.getClass().getSimpleName());
            result.put("value", obj);
        } else {
            result.put("type", obj.getClass().getSimpleName());
            result.put("value", obj);
        }

        return result;
    }

    private boolean isSimpleType(Object obj) {
        return obj instanceof String || 
               obj instanceof Number || 
               obj instanceof Boolean || 
               obj instanceof Character;
    }

    private String getArrayTypeName(Object array) {
        Class<?> componentType = array.getClass().getComponentType();
        return componentType.getSimpleName() + "[]";
    }

    private List<Map<String, Object>> inspectArrayElements(Object array, int maxDepth) {
        int length = Array.getLength(array);
        List<Map<String, Object>> elements = new ArrayList<>();

        for (int i = 0; i < length; i++) {
            Object element = Array.get(array, i);
            elements.add(inspectObject(element, maxDepth));
        }

        return elements;
    }
}

