import java.util.HashMap;
import java.util.Map;

public class UriValidator {
    public static Map<String, Object> processContentUri(String uriString) {
        Map<String, Object> result = new HashMap<>();
        result.put("isValid", true);

        String prefix = "content://";
        if (!uriString.startsWith(prefix)) {
            result.put("authority", "");
            result.put("path", "");
        } else {
            String withoutPrefix = uriString.substring(prefix.length());
            int firstSlashIndex = withoutPrefix.indexOf('/');
            if (firstSlashIndex == -1) {
                result.put("authority", withoutPrefix);
                result.put("path", "");
            } else {
                result.put("authority", withoutPrefix.substring(0, firstSlashIndex));
                result.put("path", withoutPrefix.substring(firstSlashIndex));
            }
        }

        result.put("type", "UNKNOWN");
        return result;
    }
}

