        // Parse the URI using java.net.URI which will throw URISyntaxException if malformed
        URI uri = new URI(uriString);

        result.put("isValid", true);
        result.put("authority", uri.getAuthority() != null ? uri.getAuthority() : "");
        result.put("path", uri.getPath() != null ? uri.getPath() : "");
        result.put("type", "UNKNOWN");

        return result;
    }
}

