import java.util.HashMap;
import java.util.Map;

public class PathAnalyzer {
    public static Map<String, Object> analyzePath(String filePath) {
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("Input path cannot be null or empty");
        }

        // Find the last path separator (both Unix and Windows)
        int lastSeparatorIndex = Math.max(
            filePath.lastIndexOf('/'),
            filePath.lastIndexOf('\\')
        );

        // Extract filename component
        String filename = (lastSeparatorIndex == -1) 
            ? filePath 
            : filePath.substring(lastSeparatorIndex + 1);

        // Extract extension
        String extension = "";
        int dotIndex = filename.lastIndexOf('.');
        if (dotIndex > 0) {
            extension = filename.substring(dotIndex + 1);
        }

        // Extract and normalize parent directory
        String parentDir = "";
        if (lastSeparatorIndex != -1) {
            parentDir = filePath.substring(0, lastSeparatorIndex)
                .replace('\\', '/'); // Normalize to forward slashes
        }

        Map<String, Object> result = new HashMap<>();
        result.put("filename", filename);
        result.put("extension", extension);
        result.put("parentDir", parentDir);

        return result;
    }
}

