import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.Files;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class AdvancedFileProcessor {
    private Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        this.directoryPath = Paths.get(directoryPath);
        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Path is not a directory: " + directoryPath);
        }
    }

    public Map<String, Object> processFiles() {
        Map<String, Object> result = new HashMap<>();
        int fileCount = 0;
        long totalSize = 0L;

        try {
            fileCount = (int) Files.list(directoryPath)
                    .filter(Files::isRegularFile)
                    .count();

            totalSize = Files.list(directoryPath)
                    .filter(Files::isRegularFile)
                    .mapToLong(path -> {
                        try {
                            return Files.size(path);
                        } catch (IOException e) {
                            return 0L;
                        }
                    })
                    .sum();
        } catch (IOException e) {
            // In case of IO errors, we'll return the counts we have (likely zeros)
        }

        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", "");
        result.put("wordFrequency", new HashMap<String, Integer>());

        return result;
    }
}

