public class AdvancedFileProcessor {
    private Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        this.directoryPath = Paths.get(directoryPath);
        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Path is not a directory: " + directoryPath);
        }
    }

    public Map<String, Object> processFiles() {
        Map<String, Object> result = new HashMap<>();
        int fileCount = 0;
        long totalSize = 0L;
        String largestFileName = "N/A";
        long largestFileSize = -1;
        Map<String, Integer> wordFrequency = new HashMap<>();

        try {
            // Get all regular files
            List<Path> files = Files.list(directoryPath)
                    .filter(Files::isRegularFile)
                    .collect(Collectors.toList());

            fileCount = files.size();

            if (fileCount > 0) {
                // Find the largest file
                Optional<Path> largestFile = files.stream()
                        .max((p1, p2) -> {
                            try {
                                return Long.compare(Files.size(p1), Files.size(p2));
                            } catch (IOException e) {
                                return 0;
                            }
                        });

                if (largestFile.isPresent()) {
                    Path largest = largestFile.get();
                    largestFileName = largest.getFileName().toString();
                    largestFileSize = Files.size(largest);
                }

                // Calculate total size and process word frequency
                for (Path file : files) {
                    try {
                        long fileSize = Files.size(file);
                        totalSize += fileSize;
                        processFileContent(file, wordFrequency);
                    } catch (IOException e) {
                        // Skip files that can't be read or sized
                    }
                }
            }
        } catch (IOException e) {
            // In case of IO errors, we'll return the counts we have
        }

        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", largestFileName);
        result.put("wordFrequency", wordFrequency);

        return result;
    }

    private void processFileContent(Path file, Map<String, Integer> wordFrequency) {
        try (Stream<String> lines = Files.lines(file)) {
            lines.forEach(line -> {
                String[] words = line.split("\\s+"); // Split by whitespace
                for (String word : words) {
                    // Remove non-alphabetic characters and convert to lowercase
                    String cleanedWord = word.replaceAll("[^a-zA-Z]", "").toLowerCase();
                    if (!cleanedWord.isEmpty()) {
