import java.util.List;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.text.DecimalFormat;

class PolicyData {
    private String previousRiskCode;
    private String previousRiskName;
    private String currentRiskCode;
    private String currentRiskName;
    private double premium;

    public PolicyData(String previousRiskCode, String previousRiskName, 
                     String currentRiskCode, String currentRiskName, double premium) {
        this.previousRiskCode = previousRiskCode;
        this.previousRiskName = previousRiskName;
        this.currentRiskCode = currentRiskCode;
        this.currentRiskName = currentRiskName;
        this.premium = premium;
    }

    public String getPreviousRiskCode() { return previousRiskCode; }
    public String getPreviousRiskName() { return previousRiskName; }
    public String getCurrentRiskCode() { return currentRiskCode; }
    public String getCurrentRiskName() { return currentRiskName; }
    public double getPremium() { return premium; }
}

class FinancialReportAnalyzer {

    public static class RiskSummary {
        private String riskCode;
        private String riskName;
        private double totalPremium;
        private int policyCount;

        public RiskSummary(String riskCode, String riskName) {
            this.riskCode = riskCode;
            this.riskName = riskName;
            this.totalPremium = 0.0;
            this.policyCount = 0;
        }

        public void addPolicy(double premium) {
            this.totalPremium += premium;
            this.policyCount++;
        }

        // Getters for the fields
        public String getRiskCode() { return riskCode; }
        public String getRiskName() { return riskName; }
        public double getTotalPremium() { return totalPremium; }
        public int getPolicyCount() { return policyCount; }
    }

    public Map<String, Object> analyzeFinancialData(List<PolicyData> policies) {
        Map<String, RiskSummary> preRiskMap = new HashMap<>();
        Map<String, RiskSummary> curRiskMap = new HashMap<>();
        double totalPremiums = 0.0;
        int policyCount = policies.size();
        DecimalFormat df = new DecimalFormat("0.00");

        for (PolicyData policy : policies) {
            totalPremiums += policy.getPremium();

            // Process previous risk category
            String preCode = policy.getPreviousRiskCode();
            String preName = policy.getPreviousRiskName();
            String preKey = preCode + "|" + preName;
            preRiskMap.computeIfAbsent(preKey, k -> new RiskSummary(preCode, preName))
                     .addPolicy(policy.getPremium());

            // Process current risk category
            String curCode = policy.getCurrentRiskCode();
            String curName = policy.getCurrentRiskName();
            String curKey = curCode + "|" + curName;
            curRiskMap.computeIfAbsent(curKey, k -> new RiskSummary(curCode, curName))
                     .addPolicy(policy.getPremium());
        }

        // Convert RiskSummary objects to list of maps with formatted premium
        List<Map<String, Object>> preRiskSummary = new ArrayList<>();
        for (RiskSummary summary : preRiskMap.values()) {
            Map<String, Object> summaryMap = new HashMap<>();
            summaryMap.put("riskCode", summary.getRiskCode());
            summaryMap.put("riskName", summary.getRiskName());
            summaryMap.put("premium", df.format(summary.getTotalPremium()));
            summaryMap.put("policyCount", summary.getPolicyCount());
            preRiskSummary.add(summaryMap);
        }

        List<Map<String, Object>> curRiskSummary = new ArrayList<>();
        for (RiskSummary summary : curRiskMap.values()) {
            Map<String, Object> summaryMap = new HashMap<>();
            summaryMap.put("riskCode", summary.getRiskCode());
            summaryMap.put("riskName", summary.getRiskName());
            summaryMap.put("premium", df.format(summary.getTotalPremium()));
            summaryMap.put("policyCount", summary.getPolicyCount());
            curRiskSummary.add(summaryMap);
        }

        Map<String, Object> result = new HashMap<>();
        result.put("totalPremiums", totalPremiums);
        result.put("policyCount", policyCount);
        result.put("preRiskSummary", preRiskSummary);
        result.put("curRiskSummary", curRiskSummary);

        return result;
    }
}

