import java.util.ArrayList;
import java.util.Collections;

class CargoOptimizer {

    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        int countHeavy = 0;
        ArrayList<Integer> lightItems = new ArrayList<>();
        for (int weight : weights) {
            if (weight >= capacity) {
                countHeavy++;
            } else {
                lightItems.add(weight);
            }
        }
        Collections.sort(lightItems);
        int left = 0;
        int right = lightItems.size() - 1;
        int tripsLight = 0;
        while (left <= right) {
            int current = lightItems.get(right);
            right--;
            while (current < capacity && left <= right) {
                current += lightItems.get(left);
                left++;
            }
            if (current >= capacity) {
                tripsLight++;
            } else {
                break;
            }
        }
        return countHeavy + tripsLight;
    }
}

