import java.util.ArrayList;
import java.util.Collections;

class CargoOptimizer {

    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        int countAlone = 0;
        ArrayList<Integer> lightItems = new ArrayList<>();
        for (int weight : weights) {
            if (weight >= capacity) {
                countAlone++;
            } else if (weight > 0) {
                lightItems.add(weight);
            }
        }
        Collections.sort(lightItems, Collections.reverseOrder());
        int n = lightItems.size();
        if (n == 0) {
            return countAlone;
        }
        int left = 0;
        int right = n - 1;
        int tripsLight = 0;
        while (left <= right) {
            int currentWeight = lightItems.get(left);
            int minSize = (capacity + currentWeight - 1) / currentWeight;
            if (right - left + 1 >= minSize) {
                tripsLight++;
                left++;
                right -= (minSize - 1);
            } else {
                break;
            }
        }
        return countAlone + tripsLight;
    }
}

