import java.util.ArrayList;
import java.util.Collections;

class CargoOptimizer {

    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        if (weights == null || weights.isEmpty()) {
            return 0;
        }

        ArrayList<Integer> copiedWeights = new ArrayList<>(weights);
        int countAlone = 0;
        ArrayList<Integer> groupedItems = new ArrayList<>();

        // Count items that can travel alone and collect others
        for (int weight : copiedWeights) {
            if (weight >= capacity) {
                countAlone++;
            } else if (weight > 0) {
                groupedItems.add(weight);
            }
        }

        // Sort in descending order for optimal grouping
        Collections.sort(groupedItems, Collections.reverseOrder());

        int trips = 0;
        int n = groupedItems.size();
        boolean[] used = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (used[i]) continue;

            // Calculate minimum group size needed with current heaviest item
            int minSize = (int) Math.ceil((double) capacity / groupedItems.get(i));

            // Check if remaining items can form a valid group
            if (n - i < minSize) {
                break;
            }

            // Form group with current heaviest and next lightest available items
            int groupSize = 1;
            int groupWeight = groupedItems.get(i);
            used[i] = true;

            // Add lightest available items to complete the group
            int j = n - 1;
            while (groupSize < minSize && j > i) {
                if (!used[j]) {
                    groupSize++;
                    used[j] = true;
                    j--;
                } else {
                    j--;
                }
            }

            // Verify if group meets condition
            if (groupSize * groupedItems.get(i) >= capacity) {
                trips++;
            }
        }

        return countAlone + trips;
    }
}

