public class DocumentationValidator {
    public static final Pattern INVALID_CHAR_PATTERN = Pattern.compile("\\\\");
    public static final Pattern PLACEHOLDER_PATTERN = Pattern.compile("\\$\\{([^}]*)\\}");
    public static final List<String> ALLOWED_PLACEHOLDERS = List.of("method", "class", "param", "return");

    public static void validateDocumentation(String doc, String qualifiedName) {
        if (doc == null) {
            return;
        }
        if (doc.trim().isEmpty()) {
            throw new IllegalArgumentException("Empty documentation string for: " + qualifiedName);
        }
        if (doc.length() > 500) {
            throw new IllegalArgumentException("Documentation exceeds 500 characters for: " + qualifiedName);
        }
        Matcher invalidCharMatcher = INVALID_CHAR_PATTERN.matcher(doc);
        if (invalidCharMatcher.find()) {
            throw new IllegalArgumentException("Documentation contains invalid characters: " + qualifiedName);
        }
        Matcher placeholderMatcher = PLACEHOLDER_PATTERN.matcher(doc);
        while (placeholderMatcher.find()) {
            String placeholder = placeholderMatcher.group(1);
            if (!ALLOWED_PLACEHOLDERS.contains(placeholder)) {
                throw new IllegalArgumentException("Invalid placeholder '" + placeholder + "' in documentation for: " + qualifiedName);
            }
        }
    }

    public static void validateClassDocumentation(String classDoc, String className, List<String> methodDocs) {
        validateDocumentation(classDoc, className);
        for (int i = 0; i < methodDocs.size(); i++) {
            validateDocumentation(methodDocs.get(i), className + ".method" + (i + 1));
        }
    }
}

