    public List<String> validateBudgetVersion(VersaoOrcamento version) {
        List<String> errors = new ArrayList<>();
        if (version == null) {
            errors.add("Budget version cannot be null");
        } else {
            if (version.getIdVersaoOrcamento() == null) {
                errors.add("Version ID cannot be null");
            }

            String descricaoMensagem = version.getDescricaoMensagem();
            if (descricaoMensagem == null || descricaoMensagem.trim().isEmpty()) {
                errors.add("Description message is required");
            }

            Character idtStatus = version.getIdtStatus();
            if (idtStatus == null || !"ARP".contains(idtStatus.toString())) {
                errors.add("Status must be one of 'A', 'R', or 'P'");
            }

            if (version.getDataVigencia() == null) {
                errors.add("Effective date is required");
            }
        }
        return errors;
    }

    public List<VersaoOrcamento> filterVersions(List<VersaoOrcamento> versions, Character status, Date fromDate, Date toDate) {
        List<VersaoOrcamento> filtered = new ArrayList<>();

        if (versions == null) {
            return filtered;
        }

        for (VersaoOrcamento version : versions) {
            if (status != null && !status.equals(version.getIdtStatus())) {
                continue;
            }

            Date dataVigencia = version.getDataVigencia();
            if (dataVigencia == null) {
                continue;
            }

            if (fromDate != null && dataVigencia.before(fromDate)) {
                continue;
            }

            if (toDate != null && dataVigencia.after(toDate)) {
                continue;
            }

            filtered.add(version);
        }

        return filtered;
    }
}

