        }

        int dotProduct = 0;
        for (int i = 0; i < array1.length; i++) {
            dotProduct += array1[i] * array2[i];
        }
        return dotProduct;
    }

    public static int calculateDotProduct(int[] array1, int[] array2, int threadCount) {
        if (array1 == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }
        if (array2 == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }
        if (array1.length != array2.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }
        if (threadCount <= 0) {
            throw new IllegalArgumentException("Thread count must be greater than zero");
        }

        if (array1.length == 0) {
            return 0;
        }

        // Limit threads to the minimum of threadCount and array length
        int actualThreads = Math.min(threadCount, array1.length);
        ExecutorService executor = Executors.newFixedThreadPool(actualThreads);
        List<Future<Integer>> partialSums = new ArrayList<>();

        try {
            int chunkSize = (int) Math.ceil((double) array1.length / actualThreads);

            for (int i = 0; i < actualThreads; i++) {
                int start = i * chunkSize;
                int end = Math.min(array1.length, (i + 1) * chunkSize);
                final int taskIndex = i;

                partialSums.add(executor.submit(() -> {
                    try {
                        int partialSum = 0;
                        for (int j = start; j < end; j++) {
                            partialSum += array1[j] * array2[j];
                        }
                        return partialSum;
                    } catch (Exception e) {
                        throw new RuntimeException("Error in task " + taskIndex + 
                                                  " processing indices [" + start + 
                                                  ", " + (end-1) + "]", e);
                    }
                }));
            }

            int total = 0;
            for (int i = 0; i < partialSums.size(); i++) {
                try {
                    total += partialSums.get(i).get();
                } catch (InterruptedException | ExecutionException e) {
                    Throwable cause = e.getCause();
                    if (cause instanceof RuntimeException) {
                        throw (RuntimeException) cause;
                    }
                    throw new RuntimeException("Error retrieving result from task " + i, e);
                }
            }

            return total;
        } finally {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }
}

