import java.util.*;

class TwoSatSolver {
    private List<int[]> clauses;
    private List<List<Integer>> graph;
    private List<List<Integer>> reversedGraph;
    private int n;

    public TwoSatSolver() {
        clauses = new ArrayList<>();
        n = 0;
    }

    public void addClause(int a, int b) {
        clauses.add(new int[]{a, b});
        n = Math.max(n, Math.max(Math.abs(a), Math.abs(b)));
    }

    public boolean isSatisfiable() {
        if (n == 0) return true;

        int nodes = 2 * n;
        graph = new ArrayList<>(nodes);
        reversedGraph = new ArrayList<>(nodes);
        for (int i = 0; i < nodes; i++) {
            graph.add(new ArrayList<>());
            reversedGraph.add(new ArrayList<>());
        }

        for (int[] clause : clauses) {
            int a = clause[0];
            int b = clause[1];

            int notA = literalToNode(-a, n);
            int nodeB = literalToNode(b, n);
            graph.get(notA).add(nodeB);
            reversedGraph.get(nodeB).add(notA);

            int notB = literalToNode(-b, n);
            int nodeA = literalToNode(a, n);
            graph.get(notB).add(nodeA);
