        return innerCutoff;
    }

    public void setInnerCutoff(double innerCutoff) {
        if (innerCutoff < 0 || innerCutoff > 90) {
            throw new IllegalArgumentException("Inner cutoff must be between 0 and 90 degrees");
        }
        if (outerCutoff > 0 && innerCutoff >= outerCutoff) {
            throw new IllegalArgumentException("Inner cutoff must be less than outer cutoff");
        }
        this.innerCutoff = innerCutoff;
    }

    public double getOuterCutoff() {
        return outerCutoff;
    }

    public void setOuterCutoff(double outerCutoff) {
        if (outerCutoff < 0 || outerCutoff > 90) {
            throw new IllegalArgumentException("Outer cutoff must be between 0 and 90 degrees");
        }
        if (innerCutoff > 0 && outerCutoff <= innerCutoff) {
            throw new IllegalArgumentException("Outer cutoff must be greater than inner cutoff");
        }
        this.outerCutoff = outerCutoff;
    }

    public double getFalloffExponent() {
        return falloffExponent;
    }

    public void setFalloffExponent(double falloffExponent) {
        if (falloffExponent <= 0) {
            throw new IllegalArgumentException("Falloff exponent must be positive");
        }
        this.falloffExponent = falloffExponent;
    }

    @Override
    public void setPosition(Vector3 position) {
        if (position == null) {
            throw new IllegalArgumentException("Position cannot be null");
        }
        super.setPosition(position);
    }

    @Override
    public void setIntensity(double intensity) {
        if (intensity < 0) {
            throw new IllegalArgumentException("Intensity must be non-negative");
        }
        super.setIntensity(intensity);
    }

    public double calculateIntensity(Vector3 point) {
        return 1.0;
    }
}

