import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.stream.Collectors;

class DataProcessor {

    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        List<String> categoryNames = new ArrayList<>();
        List<Integer> quantities = new ArrayList<>();

        // Parse category names
        int index = 0;
        while (index < categoriesJson.length()) {
            int nameIndex = categoriesJson.indexOf("\"name\"", index);
            if (nameIndex == -1) break;

            int colonIndex = categoriesJson.indexOf(':', nameIndex);
            int quoteStart = categoriesJson.indexOf('"', colonIndex + 1);
            int quoteEnd = categoriesJson.indexOf('"', quoteStart + 1);

            if (quoteStart == -1 || quoteEnd == -1) break;

            String name = categoriesJson.substring(quoteStart + 1, quoteEnd);
            categoryNames.add(name);
            index = quoteEnd + 1;
        }

        // Parse quantities
        index = 0;
        while (index < cartJson.length()) {
            int quantityIndex = cartJson.indexOf("\"quantity\"", index);
            if (quantityIndex == -1) break;

            int colonIndex = cartJson.indexOf(':', quantityIndex);
            int valueStart = colonIndex + 1;
            int valueEnd = cartJson.length();

            // Find the end of the value (comma or bracket)
            for (int i = valueStart; i < cartJson.length(); i++) {
                char c = cartJson.charAt(i);
                if (c == ',' || c == '}' || c == ']') {
                    valueEnd = i;
                    break;
                }
            }

            try {
                String numStr = cartJson.substring(valueStart, valueEnd).trim();
                int quantity = Integer.parseInt(numStr);
                quantities.add(quantity);
            } catch (NumberFormatException e) {
                // Skip invalid numbers
            }
            index = valueEnd + 1;
        }

        // Calculate required values
        int categoryCount = categoryNames.size();
        int totalCartItems = quantities.stream().mapToInt(Integer::intValue).sum();
        boolean hasEmptyCategories = categoryNames.stream().anyMatch(String::isEmpty);
        List<Integer> categoryNameLengths = categoryNames.stream()
                .map(String::length)
                .collect(Collectors.toList());

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryCount);
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }
}

