        if (categoriesJson == null || categoriesJson.trim().isEmpty() || 
            cartJson == null || cartJson.trim().isEmpty()) {
            return createDefaultResult(false);
        }

        // Check if both JSON strings have success field equals 1
        boolean hasValidCategories;
        boolean hasValidCart;
        try {
            hasValidCategories = parseSuccessField(categoriesJson);
            hasValidCart = parseSuccessField(cartJson);
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Invalid JSON format in success field parsing", e);
        }

        if (!hasValidCategories || !hasValidCart) {
            return createDefaultResult(false);
        }

        List<String> categoryNames;
        List<Integer> quantities;

        try {
            categoryNames = parseCategoryNames(categoriesJson);
            quantities = parseQuantities(cartJson);
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid JSON format during data parsing", e);
        }

        // Calculate required values
        int categoryCount = categoryNames.size();
        int totalCartItems = quantities.stream().mapToInt(Integer::intValue).sum();
        boolean hasEmptyCategories = categoryNames.isEmpty() || categoryNames.stream().anyMatch(String::isEmpty);
        List<Integer> categoryNameLengths = categoryNames.stream()
                .map(String::length)
                .collect(Collectors.toList());

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryCount);
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }

    private static boolean parseSuccessField(String json) {
        int successIndex = json.indexOf("\"success\"");
        if (successIndex == -1) return false;

        int colonIndex = json.indexOf(':', successIndex);
        if (colonIndex == -1) throw new IllegalArgumentException("Missing colon after success field");

        int valueStart = colonIndex + 1;
        int valueEnd = findValueEnd(json, valueStart);

        String valueStr = json.substring(valueStart, valueEnd).trim();
        if (valueStr.equals("1")) return true;
        if (valueStr.equals("0") || valueStr.equals("null")) return false;

        throw new IllegalArgumentException("Invalid value for success field: " + valueStr);
    }

    private static List<String> parseCategoryNames(String json) {
        List<String> categoryNames = new ArrayList<>();

        int index = 0;
        while (index < json.length()) {
            int nameIndex = json.indexOf("\"name\"", index);
            if (nameIndex == -1) break;

            int colonIndex = json.indexOf(':', nameIndex);
            if (colonIndex == -1) throw new IllegalArgumentException("Missing colon after name field");

            // Handle null values
            if (json.indexOf("null", colonIndex + 1) == colonIndex + 1) {
                categoryNames.add("");
                index = colonIndex + 5;
                continue;
            }

            int quoteStart = json.indexOf('"', colonIndex + 1);
            if (quoteStart == -1) {
                // Missing quote, check if it's an empty string without quotes
                int commaIndex = json.indexOf(',', colonIndex + 1);
                int braceIndex = json.indexOf('}', colonIndex + 1);
                int endIndex = Math.min(commaIndex != -1 ? commaIndex : Integer.MAX_VALUE, 
                                       braceIndex != -1 ? braceIndex : Integer.MAX_VALUE);

                if (endIndex == Integer.MAX_VALUE) {
                    throw new IllegalArgumentException("Unterminated name value");
                }

                String value = json.substring(colonIndex + 1, endIndex).trim();
                if (value.isEmpty()) {
                    categoryNames.add("");
                } else {
                    throw new IllegalArgumentException("Invalid name value format: " + value);
                }

                index = endIndex + 1;
                continue;
            }

            int quoteEnd = json.indexOf('"', quoteStart + 1);
            if (quoteEnd == -1) throw new IllegalArgumentException("Unterminated string in name field");

            String name = json.substring(quoteStart + 1, quoteEnd);
            categoryNames.add(name);
            index = quoteEnd + 1;
        }

        return categoryNames;
    }

    private static List<Integer> parseQuantities(String json) {
        List<Integer> quantities = new ArrayList<>();

        int index = 0;
        while (index < json.length()) {
            int quantityIndex = json.indexOf("\"quantity\"", index);
            if (quantityIndex == -1) break;

            int colonIndex = json.indexOf(':', quantityIndex);
            if (colonIndex == -1) throw new IllegalArgumentException("Missing colon after quantity field");

            // Handle null values
            if (json.indexOf("null", colonIndex + 1) == colonIndex + 1) {
                quantities.add(0);
                index = colonIndex + 5;
                continue;
            }

            int valueStart = colonIndex + 1;
            int valueEnd = findValueEnd(json, valueStart);

            try {
                String numStr = json.substring(valueStart, valueEnd).trim();
                if (numStr.isEmpty()) {
                    quantities.add(0);
                } else {
                    int quantity = Integer.parseInt(numStr);
                    quantities.add(quantity);
                }
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException("Invalid quantity value: " + 
                    json.substring(valueStart, valueEnd).trim(), e);
            }
            index = valueEnd + 1;
        }

        return quantities;
    }

    private static int findValueEnd(String json, int startPos) {
        int braceCount = 0;
        int bracketCount = 0;
        boolean inQuotes = false;
        boolean escapeNext = false;

        for (int i = startPos; i < json.length(); i++) {
            char c = json.charAt(i);

            if (escapeNext) {
                escapeNext = false;
                continue;
            }

            if (c == '\\') {
                escapeNext = true;
                continue;
            }

            if (c == '"') {
                inQuotes = !inQuotes;
                continue;
            }

            if (!inQuotes) {
                if (c == '{') braceCount++;
                else if (c == '}') braceCount--;
                else if (c == '[') bracketCount++;
                else if (c == ']') bracketCount--;

                if ((c == ',' || c == '}' || c == ']') && braceCount == 0 && bracketCount == 0) {
                    return i;
                }
            }
        }

        return json.length();
    }

    private static Map<String, Object> createDefaultResult(boolean hasEmptyCategories) {
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", 0);
        result.put("totalCartItems", 0);
        result.put("categoryNames", new ArrayList<String>());
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", new ArrayList<Integer>());
        return result;
    }
}

