public class GameOfLifePatterns {
    private static class Coordinate {
        public int x;
        public int y;

        public Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static boolean[][] createGrid(int size) {
        return new boolean[size][size];
    }

    public static int countLiveCells(boolean[][] grid) {
        int count = 0;
        for (boolean[] row : grid) {
            for (boolean cell : row) {
                if (cell) {
                    count++;
                }
            }
        }
        return count;
    }

    public static void applyPattern(boolean[][] grid, String patternName, int xOffset, int yOffset) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            throw new IllegalArgumentException("Grid cannot be null or empty");
        }

        if (xOffset < 0 || yOffset < 0) {
            throw new IllegalArgumentException("Offsets must be non-negative");
        }

        if (!"glider".equals(patternName)) {
            return; // Only glider pattern is implemented
        }

        // Define glider pattern coordinates
        Coordinate[] gliderPattern = {
            new Coordinate(0, 0),
            new Coordinate(1, 0),
            new Coordinate(2, 0),
            new Coordinate(2, 1),
            new Coordinate(1, 2)
        };

        // Apply pattern to grid
        for (Coordinate coord : gliderPattern) {
            int x = coord.x + xOffset;
            int y = coord.y + yOffset;

            if (x < grid.length && y < grid[0].length) {
                grid[x][y] = true;
            }
        }
    }
}

