import java.math.BigDecimal;

class TaxPriceCalculator {

    public static BigDecimal[] calculatePriceAndTax(BigDecimal totalAmount, BigDecimal taxRate, boolean isTaxIncluded) {
        if (totalAmount == null || taxRate == null) {
            throw new IllegalArgumentException("Input parameters cannot be null");
        }

        if (!isTaxIncluded) {
            BigDecimal taxAmount = totalAmount.multiply(taxRate)
                .divide(BigDecimal.valueOf(100), 2, BigDecimal.ROUND_HALF_UP);
            return new BigDecimal[] {
                totalAmount.setScale(2, BigDecimal.ROUND_HALF_UP),
                taxAmount
            };
        } else {
            BigDecimal divisor = BigDecimal.ONE.add(
                taxRate.divide(BigDecimal.valueOf(100), 10, BigDecimal.ROUND_HALF_UP)
            );
            BigDecimal price = totalAmount.divide(divisor, 10, BigDecimal.ROUND_HALF_UP)
                .setScale(2, BigDecimal.ROUND_HALF_UP);
            BigDecimal tax = totalAmount.subtract(price)
                .setScale(2, BigDecimal.ROUND_HALF_UP);
            return new BigDecimal[] { price, tax };
        }
    }
}

