import java.math.RoundingMode;

class TaxPriceCalculator {

    public static BigDecimal[] calculatePriceAndTax(BigDecimal totalAmount, BigDecimal taxRate, boolean isTaxIncluded) {
        // Input validation
        if (totalAmount == null || taxRate == null) {
            throw new IllegalArgumentException("Input parameters cannot be null");
        }
        if (totalAmount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("Total amount cannot be negative");
        }
        if (taxRate.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("Tax rate cannot be negative");
        }

        BigDecimal[] result = new BigDecimal[2];

        if (!isTaxIncluded) {
            // Price is totalAmount, tax is calculated as totalAmount * (taxRate/100)
            BigDecimal taxRateDecimal = taxRate.divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);
            BigDecimal taxAmount = totalAmount.multiply(taxRateDecimal)
                .setScale(2, RoundingMode.HALF_UP);
            result[0] = totalAmount.setScale(2, RoundingMode.HALF_UP);
            result[1] = taxAmount;
        } else {
            // Calculate price as totalAmount / (1 + taxRate/100)
            BigDecimal taxRateDecimal = taxRate.divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);
            BigDecimal denominator = BigDecimal.ONE.add(taxRateDecimal);
            BigDecimal price = totalAmount.divide(denominator, 10, RoundingMode.HALF_UP)
                .setScale(2, RoundingMode.HALF_UP);
            BigDecimal taxAmount = totalAmount.subtract(price)
                .setScale(2, RoundingMode.HALF_UP);
            result[0] = price;
            result[1] = taxAmount;
        }

        return result;
    }
}

