    private final Map<String, Consumer<Map<String, Object>>> messageHandlers;
    private final BiConsumer<String, String> errorLogger;
    private final RateLimiter rateLimiter;

    public WebSocketMessageHandler(BiConsumer<String, String> errorLogger) {
        this.messageHandlers = new ConcurrentHashMap<>();
        this.errorLogger = errorLogger;
        this.rateLimiter = new RateLimiter(100, 1000); // 100 messages per second
    }

    public void addMessageHandler(String messageType, Consumer<Map<String, Object>> handler) {
        messageHandlers.put(messageType, handler);
    }

    public boolean processMessage(String messageType, Map<String, Object> messageData) {
        // Check rate limiting first
        if (!rateLimiter.tryAcquire()) {
            return false;
        }

        // Validate inputs
        if (messageType == null || messageType.trim().isEmpty() || messageData == null) {
            return false;
        }

        Consumer<Map<String, Object>> handler = messageHandlers.get(messageType);
        if (handler != null) {
            try {
                handler.accept(messageData);
                return true;
            } catch (Exception e) {
                errorLogger.accept(messageType, "Error processing message: " + e.getMessage());
                return true;
            }
        }
        return false;
    }

    private static class RateLimiter {
        private final int maxRequests;
        private final long timeWindowMs;
        private final Queue<Long> requestTimestamps;

        public RateLimiter(int maxRequests, long timeWindowMs) {
            this.maxRequests = maxRequests;
            this.timeWindowMs = timeWindowMs;
            this.requestTimestamps = new ConcurrentLinkedQueue<>();
        }

        public synchronized boolean tryAcquire() {
            long currentTime = System.currentTimeMillis();
            long cutoffTime = currentTime - timeWindowMs;

            // Remove timestamps older than the time window
            while (!requestTimestamps.isEmpty() && requestTimestamps.peek() < cutoffTime) {
