        requiredOptions.add("backend");
        requiredOptions.add("doctype");

        // Initialize option dependencies
        Set<String> templateEngineDeps = new HashSet<>();
        templateEngineDeps.add("template_dirs");
        optionDependencies.put("template_engine", templateEngineDeps);
    }

    public void setOption(String option, Object value) {
        options.put(option, value);
    }

    public Object getOption(String option) {
        if (options.containsKey(option)) {
            return options.get(option);
        } else if (defaultOptions.containsKey(option)) {
            return defaultOptions.get(option);
        }
        return null;
    }
}

