public class KeyValueStore {
    private final ConcurrentHashMap<String, String> store;
    private final ConcurrentHashMap<String, AtomicInteger> accessCounts;
    private final ConcurrentHashMap<String, Long> lastAccessTimes;
    private final ConcurrentHashMap<Class<?>, AtomicInteger> typeCounts;

    public KeyValueStore() {
        this.store = new ConcurrentHashMap<>();
        this.accessCounts = new ConcurrentHashMap<>();
        this.lastAccessTimes = new ConcurrentHashMap<>();
        this.typeCounts = new ConcurrentHashMap<>();
    }

    public void put(String key, String value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        String oldValue = store.put(key, value);

        // Update type counts
        if (oldValue != null) {
            // Decrement count for old value's type
            Class<?> oldType = oldValue.getClass();
            typeCounts.computeIfPresent(oldType, (cls, count) -> {
                count.decrementAndGet();
                return count.get() == 0 ? null : count;
            });
        }

        // Increment count for new value's type
        if (value != null) {
            Class<?> newType = value.getClass();
            typeCounts.compute(newType, (cls, count) -> {
                if (count == null) {
                    return new AtomicInteger(1);
                }
                count.incrementAndGet();
                return count;
            });
        }
    }

    public void putAll(Map<String, String> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries cannot be null");
        }
        for (Map.Entry<String, String> entry : entries.entrySet()) {
            put(entry.getKey(), entry.getValue());
        }
    }

    public String get(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        AtomicInteger count = accessCounts.computeIfAbsent(key, k -> new AtomicInteger(0));
        count.incrementAndGet();

        long currentTime = System.currentTimeMillis();
        lastAccessTimes.put(key, currentTime);

        return store.get(key);
    }

    public int getAccessCount(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        AtomicInteger count = accessCounts.get(key);
        return count == null ? 0 : count.get();
    }

    public long getLastAccessTime(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        Long time = lastAccessTimes.get(key);
        return time == null ? 0 : time;
    }

    public int getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
        AtomicInteger count = typeCounts.get(type);
        return count == null ? 0 : count.get();
    }

    public Set<String> findKeysByType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
        return store.entrySet().stream()
                .filter(entry -> entry.getValue() != null && entry.getValue().getClass().equals(type))
                .map(Map.Entry::getKey)
                .collect(Collectors.toSet());
    }

    public void clear() {
        store.clear();
        accessCounts.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }

    public Statistics computeStatistics() {
        Statistics stats = new Statistics();
        stats.totalEntries = store.size();

        // Find key with max access count
        accessCounts.entrySet().stream()
                .max(Map.Entry.comparingByValue(Comparator.comparingInt(AtomicInteger::get)))
                .ifPresent(entry -> stats.keyWithMaxAccess = entry.getKey());

        // Calculate type distribution
        stats.typeDistribution = typeCounts.entrySet().stream()
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        entry -> entry.getValue().get()
                ));

        // Estimate memory usage (approximate)
        stats.estimatedMemoryUsage = store.entrySet().stream()
                .mapToLong(entry -> {
                    long keySize = entry.getKey() != null ? entry.getKey().length() * 2L : 0;
                    long valueSize = entry.getValue() != null ? entry.getValue().length() * 2L : 0;
                    return keySize + valueSize + 40; // Add overhead for map entry (approximate)
                })
                .sum();

        return stats;
    }

    public static class Statistics {
        public int totalEntries;
        public String keyWithMaxAccess;
        public Map<Class<?>, Integer> typeDistribution;
        public long estimatedMemoryUsage;

        @Override
        public String toString() {
            return "Statistics{" +
                    "totalEntries=" + totalEntries +
                    ", keyWithMaxAccess='" + keyWithMaxAccess + '\'' +
                    ", typeDistribution=" + typeDistribution +
                    ", estimatedMemoryUsage=" + estimatedMemoryUsage +
                    '}';
        }
    }
}

