public class NavalBattleAdapter extends Observable {
    private Set<String> shipPositions;
    private Set<String> attackPositions;
    private Set<String> hitPositions;
    private boolean gameOver;
    private String winner;

    public enum HitResult {
        HIT, MISS, SUNK
    }

    public enum EventType {
        SHIPS_PLACED, HIT, MISS, GAME_OVER
    }

    public NavalBattleAdapter() {
        this.shipPositions = new HashSet<>();
        this.attackPositions = new HashSet<>();
        this.hitPositions = new HashSet<>();
        this.gameOver = false;
        this.winner = null;
    }

    public void placeShips(List<String> coordinates) {
        if (coordinates == null || coordinates.isEmpty()) {
            throw new IllegalArgumentException("Coordinates list cannot be null or empty");
        }
        shipPositions.addAll(coordinates);
        notifyStateChange(EventType.SHIPS_PLACED, null);
    }

    public HitResult receiveAttack(String coordinate) {
        if (coordinate == null || coordinate.isEmpty()) {
            throw new IllegalArgumentException("Coordinate cannot be null or empty");
        }

        attackPositions.add(coordinate);

        if (shipPositions.contains(coordinate)) {
            hitPositions.add(coordinate);

            if (hitPositions.equals(shipPositions)) {
                gameOver = true;
                winner = "Opponent";
                notifyStateChange(EventType.HIT, coordinate);
                notifyStateChange(EventType.GAME_OVER, null);
                return HitResult.SUNK;
            }

            notifyStateChange(EventType.HIT, coordinate);
            return HitResult.HIT;
        } else {
            notifyStateChange(EventType.MISS, coordinate);
            return HitResult.MISS;
        }
    }

    public GameState getGameState() {
        return new GameState(
            new HashSet<>(shipPositions),
            new HashSet<>(attackPositions),
            gameOver,
            winner
        );
    }

    private void notifyStateChange(EventType eventType, String coordinate) {
        setChanged();
        notifyObservers(new StateChange(eventType, coordinate));
    }

    public static class GameState {
        private final Set<String> remainingShips;
        private final Set<String> attacksMade;
        private final boolean gameOver;
        private final String winner;

        public GameState(Set<String> remainingShips, Set<String> attacksMade, boolean gameOver, String winner) {
            this.remainingShips = remainingShips;
            this.attacksMade = attacksMade;
            this.gameOver = gameOver;
            this.winner = winner;
