        if (lettersOnly.isEmpty()) {
            return "";
        }

        // Convert to title case: first letter uppercase, rest lowercase
        String firstChar = lettersOnly.substring(0, 1).toUpperCase();
        String restChars = lettersOnly.substring(1).toLowerCase();

        return firstChar + restChars;
    }
}

