import java.util.*;

class GraphAnalyzer {
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        int n = graph.length;
        int[] distances = new int[n];
        int[] prev = new int[n];
        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(prev, -1);
        distances[source] = 0;

        PriorityQueue<Vertex> pq = new PriorityQueue<>(Comparator.comparingInt(v -> v.distance));
        pq.offer(new Vertex(source, 0));

        while (!pq.isEmpty()) {
            Vertex current = pq.poll();
            int u = current.index;
            if (current.distance != distances[u]) continue;

            for (int v = 0; v < n; v++) {
                int weight = graph[u][v];
                if (weight > 0 && distances[u] + weight < distances[v]) {
                    distances[v] = distances[u] + weight;
                    prev[v] = u;
                    pq.offer(new Vertex(v, distances[v]));
                }
            }
        }

        List<List<Integer>> paths = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            paths.add(distances[i] == Integer.MAX_VALUE ? Collections.emptyList() : buildPath(prev, source, i));
        }

        Map<String, Object> result = new HashMap<>();
        result.put("distances", distances);
        result.put("paths", paths);
        return result;
    }

    private static List<Integer> buildPath(int[] prev, int source, int target) {
        LinkedList<Integer> path = new LinkedList<>();
        for (int v = target; v != -1; v = prev[v]) {
            path.addFirst(v);
        }
        return path;
    }

    private static class Vertex {
        int index;
        int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }
}

