import java.util.*;
import java.util.concurrent.*;

class MessageProducer {
    private final BlockingQueue<String> messageQueue;
    private final List<String> sentMessages;
    private final int maxRetries;
    private final long retryDelayMs;

    public MessageProducer() {
        this(new LinkedBlockingQueue<>(), 3, 100);
    }

    public MessageProducer(BlockingQueue<String> messageQueue, int maxRetries, long retryDelayMillis) {
        this.messageQueue = messageQueue;
        this.sentMessages = new ArrayList<>();
        this.maxRetries = maxRetries;
        this.retryDelayMs = retryDelayMillis;
    }

    public void sendMessages(String prefix, int count) {
        for (int i = 1; i <= count; i++) {
            String message = prefix + " " + i;
            boolean messageAdded = false;

            for (int attempt = 0; attempt < maxRetries; attempt++) {
                try {
                    if (messageQueue.offer(message, 100, TimeUnit.MILLISECONDS)) {
                        sentMessages.add(message);
                        messageAdded = true;
                        break;
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Thread interrupted while offering message", e);
                }

                if (attempt < maxRetries - 1) {
                    try {
                        Thread.sleep(retryDelayMs);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        throw new RuntimeException("Thread interrupted during retry delay", e);
                    }
                }
            }

            if (!messageAdded) {
                throw new RuntimeException("Failed to add message '" + message + "' after " + maxRetries + " attempts");
            }
        }
    }

    public BlockingQueue<String> getMessageQueue() {
        return messageQueue;
    }
}

