import java.util.Collections;

class BinaryTree<T extends Comparable<T>> {
    private Node<T> root;

    private static class Node<T> {
        T data;
        Node<T> left, right;

        Node(T data) {
            this.data = data;
        }
    }

    public void insert(T data) {
        root = insertRec(root, data);
    }

    private Node<T> insertRec(Node<T> node, T data) {
        if (node == null) {
            return new Node<>(data);
        }

        if (data.compareTo(node.data) < 0) {
            node.left = insertRec(node.left, data);
        } else if (data.compareTo(node.data) > 0) {
            node.right = insertRec(node.right, data);
        }

        return node;
    }

    public List<T> inOrderTraversal() {
        List<T> result = new ArrayList<>();
        inOrderRec(root, result);
        return result;
    }

    private void inOrderRec(Node<T> node, List<T> result) {
        if (node != null) {
            inOrderRec(node.left, result);
            result.add(node.data);
            inOrderRec(node.right, result);
        }
    }

    // Clear method needed for AdvancedTreeLoader
    public void clear() {
        root = null;
    }
}

class AdvancedTreeLoader {
    public <T extends Comparable<T>> void load(BinaryTree<T> tree, List<T> data, boolean shouldSort) {
        if (shouldSort) {
            List<T> sortedData = new ArrayList<>(data);
            Collections.sort(sortedData);
            tree.clear();
            loadBalanced(tree, sortedData, 0, sortedData.size() - 1);
        } else {
            tree.clear();
            for (T item : data) {
                tree.insert(item);
            }
        }
    }

    private <T extends Comparable<T>> void loadBalanced(BinaryTree<T> tree, List<T> data, int start, int end) {
        if (start > end) {
            return;
        }

        int mid = start + (end - start) / 2;
        tree.insert(data.get(mid));
        loadBalanced(tree, data, start, mid - 1);
        loadBalanced(tree, data, mid + 1, end);
    }
}

