            loadBalanced(tree, sortedData, 0, sortedData.size() - 1);
        } else {
            // Insert elements in original order without sorting
            for (T item : data) {
                tree.insert(item);
            }
        }
    }

    private <T> void checkForDuplicates(List<T> data) {
        Set<T> seen = new HashSet<>();
        for (T item : data) {
            if (seen.contains(item)) {
                throw new IllegalArgumentException("Duplicate elements found: " + item);
            }
            seen.add(item);
        }
    }

    private <T extends Comparable<T>> void loadBalanced(BinaryTree<T> tree, List<T> data, int start, int end) {
        if (start > end) {
            return;
        }

        int mid = start + (end - start) / 2;
        tree.insert(data.get(mid));
        loadBalanced(tree, data, start, mid - 1);
        loadBalanced(tree, data, mid + 1, end);
    }
}
