        prev = null;
        return inOrderCheck(root);
    }

    private static boolean inOrderCheck(BSTNode node) {
        if (node == null) {
            return true;
        }

        if (!inOrderCheck(node.left)) {
            return false;
        }

        if (prev != null && node.value <= prev) {
            return false;
        }
        prev = node.value;

        return inOrderCheck(node.right);
    }
