        double totalScore = 0;
        double totalComments = 0;

        for (RedditFeedItem item : validItems) {
            totalScore += item.getScore();
            totalComments += item.getNumComments();
        }

        double avgScore = totalScore / count;
        double avgComments = totalComments / count;

        return String.format("Feed Analysis Summary:\nTotal items: %d\nAverage score: %.2f\nAverage comments: %.2f", 
                           count, avgScore, avgComments);
    }
}

