import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;

public class RedditFeedAnalyzer {
    public String analyzeAndFormatFeed(List<RedditFeedItem> items, int minScore) {
        if (items == null || items.isEmpty()) {
            return "No feed items to analyze";
        }

        List<RedditFeedItem> validItems = new ArrayList<>();

        for (RedditFeedItem item : items) {
            if (item.getScore() >= minScore) {
                validItems.add(item);
            }
        }

        int count = validItems.size();

        if (count == 0) {
            return "Feed Analysis Summary:\nTotal items: 0\nAverage score: 0.00\nAverage comments: 0.00\nTop 3 items by score:";
        }

        double totalScore = 0;
        double totalComments = 0;

        for (RedditFeedItem item : validItems) {
            totalScore += item.getScore();
            totalComments += item.getNumComments();
        }

        double avgScore = totalScore / count;
        double avgComments = totalComments / count;

        // Sort items by score in descending order
        Collections.sort(validItems, new Comparator<RedditFeedItem>() {
            @Override
            public int compare(RedditFeedItem item1, RedditFeedItem item2) {
                return Integer.compare(item2.getScore(), item1.getScore());
            }
        });

        StringBuilder result = new StringBuilder();
        result.append(String.format("Feed Analysis Summary:\nTotal items: %d\nAverage score: %.2f\nAverage comments: %.2f\nTop 3 items by score:\n", 
                                   count, avgScore, avgComments));

        // Add top 3 items or all if less than 3
        int topCount = Math.min(3, validItems.size());
        for (int i = 0; i < topCount; i++) {
            RedditFeedItem item = validItems.get(i);
            result.append(String.format("%d. %s (Score: %d, Comments: %d)\n", 
                                       i + 1, item.getTitle(), item.getScore(), item.getNumComments()));
        }

        return result.toString();
    }
}

