import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class UserManager {
    private List<User> users;
    private Map<String, Integer> failedAttempts;
    private Map<String, Boolean> lockedAccounts;

    public UserManager() {
        this.users = new ArrayList<>();
        this.failedAttempts = new HashMap<>();
        this.lockedAccounts = new HashMap<>();
    }

    public Map<String, Object> registerUser(User user) {
        Map<String, Object> result = new HashMap<>();

        // Check for empty username
        if (user.getUsername() == null || user.getUsername().trim().isEmpty()) {
            result.put("success", false);
            result.put("message", "Username cannot be empty");
            return result;
        }

        // Check for empty password
        if (user.getPassword() == null || user.getPassword().trim().isEmpty()) {
            result.put("success", false);
            result.put("message", "Password cannot be empty");
            return result;
        }

        // Check for unique username (case-insensitive)
        String newUsername = user.getUsername().toLowerCase();
        for (User existingUser : users) {
            if (existingUser.getUsername().equalsIgnoreCase(newUsername)) {
                result.put("success", false);
                result.put("message", "Username already exists");
                return result;
            }
        }

        // All checks passed, add user to list
        users.add(user);
        result.put("success", true);
        result.put("message", "User registered successfully");
        return result;
    }

    public Map<String, Object> loginUser(String username, String password) {
        Map<String, Object> result = new HashMap<>();
        String usernameLower = username.toLowerCase();

        // Check if account is locked
        if (lockedAccounts.containsKey(usernameLower) && lockedAccounts.get(usernameLower)) {
            result.put("success", false);
            result.put("message", "Account is locked due to too many failed attempts");
            result.put("attemptsRemaining", 0);
            return result;
        }

        // Find user by username (case-insensitive)
        User foundUser = null;
        for (User user : users) {
            if (user.getUsername().equalsIgnoreCase(usernameLower)) {
                foundUser = user;
                break;
            }
        }

        // Check if user exists and credentials match
        if (foundUser != null && foundUser.getPassword().equals(password)) {
            // Successful login - reset failed attempts
            failedAttempts.remove(usernameLower);
            result.put("success", true);
            result.put("message", "Login successful");
            result.put("user", foundUser);
            return result;
        }

        // Failed login - increment attempts or initialize if first attempt
        int attempts = failedAttempts.getOrDefault(usernameLower, 0) + 1;
        failedAttempts.put(usernameLower, attempts);
        int remaining = 3 - attempts;

        if (remaining <= 0) {
            // Lock the account
            lockedAccounts.put(usernameLower, true);
            result.put("success", false);
            result.put("message", "Account locked due to too many failed attempts");
            result.put("attemptsRemaining", 0);
        } else {
            result.put("success", false);
            result.put("message", "Invalid credentials");
            result.put("attemptsRemaining", remaining);
        }

        return result;
    }
}

