package user.manager;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

public class UserManager {
    private List<User> users;
    private Map<String, Integer> failedAttempts;
    private Map<String, Boolean> lockedAccounts;

    public UserManager() {
        this.users = new ArrayList<>();
        this.failedAttempts = new HashMap<>();
        this.lockedAccounts = new HashMap<>();
    }

    // ... existing registerUser and loginUser methods ...

    public List<User> searchUsers(String usernameFilter, String emailFilter, int page, int pageSize) {
        // Filter users based on partial matching criteria
        List<User> filteredUsers = users.stream()
                .filter(user -> usernameFilter == null || usernameFilter.isEmpty() || 
                        user.getUsername().toLowerCase().contains(usernameFilter.toLowerCase()))
                .filter(user -> emailFilter == null || emailFilter.isEmpty() || 
                        user.getEmail().toLowerCase().contains(emailFilter.toLowerCase()))
                .collect(Collectors.toList());

        // Calculate pagination bounds
        int startIndex = (page - 1) * pageSize;
        int endIndex = Math.min(startIndex + pageSize, filteredUsers.size());

        // Return empty list if start index is beyond the filtered results
        if (startIndex >= filteredUsers.size() || startIndex < 0) {
            return new ArrayList<>();
        }

        // Return the paginated sublist
        return filteredUsers.subList(startIndex, endIndex);
    }
}

