import java.util.*;

public class AdditionChainFinder {
    public List<Integer> findShortestAdditionChain(int target) {
        List<Integer> chain = new ArrayList<>();
        chain.add(1);
        if (target == 1) {
            return chain;
        }

        int minDepth = (int) (Math.log(target) / Math.log(2)) + 1;
        for (int depth = minDepth; depth <= 100; depth++) {
            if (dfs(chain, depth, target)) {
                return chain;
            }
        }

        return chain;
    }

    private boolean dfs(List<Integer> chain, int maxDepth, int target) {
        int currentDepth = chain.size();
        int last = chain.get(currentDepth - 1);
        if (last == target) {
            return true;
        }
        if (currentDepth >= maxDepth) {
            return false;
        }

        long value = last;
        int steps = maxDepth - currentDepth;
        for (int i = 0; i < steps; i++) {
            value *= 2;
            if (value >= target) {
                break;
            }
        }
        if (value < target) {
            return false;
        }

        Set<Integer> candidateSet = new HashSet<>();
        for (int i = chain.size() - 1; i >= 0; i--) {
            int x = chain.get(i);
            int sum = last + x;
            if (sum <= target && sum > last) {
                candidateSet.add(sum);
            }
        }

        List<Integer> candidates = new ArrayList<>(candidateSet);
        Collections.sort(candidates, Collections.reverseOrder());

        for (int candidate : candidates) {
            chain.add(candidate);
            if (dfs(chain, maxDepth, target)) {
                return true;
            }
            chain.remove(chain.size() - 1);
        }

        return false;
    }
}

