import java.util.*;

public class AdditionChainFinder {
    public List<Integer> findShortestAdditionChain(int target) {
        if (target < 1) {
            throw new IllegalArgumentException("Target number must be at least 1, but was: " + target);
        }
        if (target == 1) {
            return Arrays.asList(1);
        }

        int lowerBound = (int) (Math.log(target) / Math.log(2)) + 1;
        for (int depth = lowerBound; depth <= 100; depth++) {
            List<Integer> bestChain = new ArrayList<>();
            List<Integer> chain = new ArrayList<>();
            chain.add(1);
            dfs(chain, depth, target, bestChain);
            if (!bestChain.isEmpty()) {
                return bestChain;
            }
        }

        return Collections.emptyList();
    }

    private void dfs(List<Integer> chain, int depth, int target, List<Integer> bestChain) {
        int currentDepth = chain.size();
        int last = chain.get(currentDepth - 1);

        if (currentDepth == depth) {
            if (last == target) {
                if (bestChain.isEmpty() || isLexicographicallySmaller(chain, bestChain)) {
                    bestChain.clear();
                    bestChain.addAll(chain);
                }
            }
            return;
        }

        if (!bestChain.isEmpty()) {
            for (int i = 0; i < currentDepth; i++) {
                if (chain.get(i) > bestChain.get(i)) {
                    return;
                } else if (chain.get(i) < bestChain.get(i)) {
                    break;
                }
            }
        }

        if (last * (1L << (depth - currentDepth)) < target) {
            return;
        }

        Set<Integer> candidateSet = new HashSet<>();
        for (int i = 0; i < currentDepth; i++) {
            for (int j = i; j < currentDepth; j++) {
                int sum = chain.get(i) + chain.get(j);
                if (sum > last && sum <= target) {
                    candidateSet.add(sum);
                }
            }
        }

        List<Integer> candidates = new ArrayList<>(candidateSet);
        Collections.sort(candidates);

        for (int candidate : candidates) {
            chain.add(candidate);
            dfs(chain, depth, target, bestChain);
            chain.remove(chain.size() - 1);
        }
    }

    private boolean isLexicographicallySmaller(List<Integer> chain1, List<Integer> chain2) {
        for (int i = 0; i < chain1.size(); i++) {
            if (chain1.get(i) < chain2.get(i)) {
                return true;
            } else if (chain1.get(i) > chain2.get(i)) {
                return false;
            }
        }
        return false;
    }
}

