        for (int i = 0; i < chain1.size(); i++) {
            if (chain1.get(i) < chain2.get(i)) {
                return true;
            } else if (chain1.get(i) > chain2.get(i)) {
                return false;
            }
        }
        return false;
    }

    public static boolean validateAdditionChain(List<Integer> chain, int target) {
        if (chain == null || chain.isEmpty()) {
            return false;
        }

        if (chain.get(0) != 1) {
            return false;
        }

        if (chain.get(chain.size() - 1) != target) {
            return false;
        }

        for (int i = 1; i < chain.size(); i++) {
            int current = chain.get(i);
            boolean valid = false;

            for (int j = 0; j < i; j++) {
                for (int k = 0; k < i; k++) {
                    if (chain.get(j) + chain.get(k) == current) {
                        valid = true;
                        break;
                    }
                }
                if (valid) {
                    break;
                }
            }

            if (!valid) {
                return false;
            }
        }

        return true;
    }
}
