public class PaginationManager {

    public static class PaginationResult {
        public final int totalItems;
        public final int pageSize;
        public final int currentPage;
        public final int totalPages;
        public final int startItem;
        public final int endItem;
        public final List<Integer> visiblePages;

        public PaginationResult(int totalItems, int pageSize, int currentPage, int totalPages, int startItem, int endItem, List<Integer> visiblePages) {
            this.totalItems = totalItems;
            this.pageSize = pageSize;
            this.currentPage = currentPage;
            this.totalPages = totalPages;
            this.startItem = startItem;
            this.endItem = endItem;
            this.visiblePages = visiblePages;
        }
    }

    public PaginationResult calculatePagination(int totalItems, int pageSize, int currentPage) {
        if (totalItems < 0) {
            throw new IllegalArgumentException("totalItems must be non-negative");
        }
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be positive");
        }
        if (currentPage <= 0) {
            throw new IllegalArgumentException("currentPage must be positive");
        }

        int totalPages = (int) Math.ceil((double) totalItems / pageSize);

        // Adjust currentPage if it exceeds totalPages
        if (currentPage > totalPages) {
            currentPage = totalPages;
        }

        // Handle zero totalItems case
        int startItem;
        int endItem;
        List<Integer> visiblePages;

        if (totalItems == 0) {
            totalPages = 0;
            startItem = 0;
            endItem = 0;
            visiblePages = new ArrayList<>();
        } else {
            startItem = (currentPage - 1) * pageSize + 1;
            endItem = Math.min(currentPage * pageSize, totalItems);

            // Generate visiblePages list using the new method
            visiblePages = calculateVisiblePages(totalPages, currentPage);
        }

        return new PaginationResult(totalItems, pageSize, currentPage, totalPages, startItem, endItem, visiblePages);
    }

    private List<Integer> calculateVisiblePages(int totalPages, int currentPage) {
        List<Integer> visiblePages = new ArrayList<>();

        if (totalPages == 0) {
            return visiblePages;
        }

        // Always add the first page
        visiblePages.add(1);

        // Calculate the visible page range
        int windowStart = Math.max(2, currentPage - 2);
        int windowEnd = Math.min(totalPages - 1, currentPage + 2);

        // Add ellipsis if there's a gap between first page and window start
        if (windowStart > 2) {
            visiblePages.add(-1);
        }

        // Add pages in the window
        for (int i = windowStart; i <= windowEnd; i++) {
            visiblePages.add(i);
        }

        // Add ellipsis if there's a gap between window end and last page
        if (windowEnd < totalPages - 1) {
            visiblePages.add(-1);
        }

        // Add last page if there is more than one page
        if (totalPages > 1) {
            visiblePages.add(totalPages);
        }

        return visiblePages;
    }
}

