                return root.left;
            } else {
                int minVal = minValue(root.right);
                root.val = minVal;
                root.right = deleteNode(root.right, minVal);
            }
        }
        return root;
    }

    private int minValue(TreeNode root) {
        TreeNode current = root;
        while (current.left != null) {
            current = current.left;
