    public String levelOrder(TreeNode root) {
        if (root == null) {
            return "[]";
        }

        StringBuilder result = new StringBuilder("[");
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int nonNullCount = 1;

        while (nonNullCount > 0) {
            int levelSize = queue.size();
            nonNullCount = 0;

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();

                if (node == null) {
                    queue.offer(null);
                    queue.offer(null);
                    result.append("null,");
                } else {
                    result.append(node.val).append(",");
                    queue.offer(node.left);
                    queue.offer(node.right);
                    if (node.left != null) nonNullCount++;
                    if (node.right != null) nonNullCount++;
                }
            }
        }

        // Remove trailing nulls and last comma
        int lastIndex = result.length() - 1;
        while (lastIndex >= 0 && (result.charAt(lastIndex) == ',' || result.charAt(lastIndex) == 'l' || 
               result.charAt(lastIndex) == 'u' || result.charAt(lastIndex) == 'n' || result.charAt(lastIndex) == 't')) {
            if (result.charAt(lastIndex) == ',') {
                result.deleteCharAt(lastIndex);
            } else if (lastIndex >= 3 && result.substring(lastIndex - 3, lastIndex + 1).equals("null")) {
                result.delete(lastIndex - 3, lastIndex + 1);
                lastIndex -= 4;
                continue;
            }
            lastIndex--;
        }

        // Handle case where all elements were removed
        if (result.length() == 1) {
            return "[]";
        }

        // Remove trailing comma if exists
        if (result.charAt(result.length() - 1) == ',') {
            result.deleteCharAt(result.length() - 1);
        }

        result.append("]");
        return result.toString();
    }
}

