import java.util.ArrayList;
import java.util.List;

public class EnhancedBinaryHeap {
    private List<Integer> heap;
    private int size;

    public EnhancedBinaryHeap() {
        heap = new ArrayList<>();
        size = 0;
    }

    public void insert(int value) {
        heap.add(value);
        heapifyUp(size);
        size++;
    }

    public int deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        int root = heap.get(0);
        heap.set(0, heap.get(size - 1));
        heap.remove(size - 1);
        size--;
        if (!isEmpty()) {
            heapifyDown(0);
        }
        return root;
    }

    public int peekRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return heap.get(0);
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }

    public void makeEmpty() {
        heap.clear();
        size = 0;
    }

    private void heapifyUp(int index) {
        int current = index;
        while (current > 0) {
            int parent = (current - 1) / 2;
            if (heap.get(current) < heap.get(parent)) {
                swap(current, parent);
                current = parent;
            } else {
                break;
            }
        }
    }

    private void heapifyDown(int index) {
        int current = index;
        while (current < size) {
            int leftChild = 2 * current + 1;
            int rightChild = 2 * current + 2;
            int smallest = current;

            if (leftChild < size && heap.get(leftChild) < heap.get(smallest)) {
                smallest = leftChild;
            }
            if (rightChild < size && heap.get(rightChild) < heap.get(smallest)) {
                smallest = rightChild;
            }

            if (smallest != current) {
                swap(current, smallest);
                current = smallest;
            } else {
                break;
            }
        }
    }

    private void swap(int i, int j) {
        int temp = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, temp);
    }
}

