import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;

class TimeDifferenceCalculator {
    private static final String DEFAULT_DATETIME_PATTERN = "yyyy-MM-dd HH:mm:ss";

    public static Map<String, Object> calculateDetailedTimeDifference(String earlierTime, String laterTime) 
            throws ParseException {
        SimpleDateFormat sdf = new SimpleDateFormat(DEFAULT_DATETIME_PATTERN);
        Date earlierDate = sdf.parse(earlierTime);
        Date laterDate = sdf.parse(laterTime);

        long diffMs = laterDate.getTime() - earlierDate.getTime();
        boolean isNegative = diffMs < 0;
        long absDiffMs = Math.abs(diffMs);

        long totalSeconds = absDiffMs / 1000;
        long weeks = totalSeconds / (7 * 24 * 60 * 60);
        long remainingSeconds = totalSeconds % (7 * 24 * 60 * 60);
        long days = remainingSeconds / (24 * 60 * 60);
        remainingSeconds %= (24 * 60 * 60);
        long hours = remainingSeconds / (60 * 60);
        remainingSeconds %= (60 * 60);
        long minutes = remainingSeconds / 60;
        long seconds = remainingSeconds % 60;

        if (isNegative) {
            weeks = -weeks;
            days = -days;
            hours = -hours;
            minutes = -minutes;
            seconds = -seconds;
        }

        StringBuilder humanReadable = new StringBuilder();
        if (isNegative) {
            humanReadable.append("- ");
        }

        boolean hasContent = false;
        if (weeks != 0) {
            humanReadable.append(Math.abs(weeks)).append(Math.abs(weeks) == 1 ? " week " : " weeks ");
            hasContent = true;
        }
        if (days != 0) {
            humanReadable.append(Math.abs(days)).append(Math.abs(days) == 1 ? " day " : " days ");
            hasContent = true;
        }
        if (hours != 0) {
            humanReadable.append(Math.abs(hours)).append(Math.abs(hours) == 1 ? " hour " : " hours ");
            hasContent = true;
        }
        if (minutes != 0) {
            humanReadable.append(Math.abs(minutes)).append(Math.abs(minutes) == 1 ? " minute " : " minutes ");
            hasContent = true;
        }
        if (seconds != 0 || !hasContent) {
            humanReadable.append(Math.abs(seconds)).append(Math.abs(seconds) == 1 ? " second" : " seconds");
        }

        Map<String, Object> result = new HashMap<>();
        result.put("weeks", weeks);
        result.put("days", days);
        result.put("hours", hours);
        result.put("minutes", minutes);
        result.put("seconds", seconds);
        result.put("humanReadable", humanReadable.toString().trim());

        return result;
    }
}

