                    dp[i][j] = 0;
                    continue;
                }
                if (i > 0) {
                    dp[i][j] += dp[i - 1][j];
                }
                if (j > 0) {
                    dp[i][j] += dp[i][j - 1];
                }
            }
        }

        int totalPaths = dp[rows - 1][cols - 1];
        int pathLength = rows + cols - 2;
        List<String> samplePath = new ArrayList<>();

        if (totalPaths > 0) {
            int i = rows - 1;
            int j = cols - 1;
            LinkedList<String> pathStack = new LinkedList<>();
            pathStack.push("(" + i + "," + j + ")");
            while (i != 0 || j != 0) {
