class EnhancedTrie {
    private static class TrieNode {
        char data;
        boolean isEnd;
        TrieNode[] children;

        TrieNode(char c) {
            data = c;
            isEnd = false;
            children = new TrieNode[0];
        }
    }

    private TrieNode root;

    public EnhancedTrie() {
        root = new TrieNode('\0');
    }

    public void add(String item) {
        TrieNode current = root;
        for (char c : item.toCharArray()) {
            int index = binarySearch(current.children, c);
            if (index >= 0) {
                current = current.children[index];
            } else {
                TrieNode newNode = new TrieNode(c);
                int insertIndex = -index - 1;
                current.children = insert(current.children, newNode, insertIndex);
                current = newNode;
            }
        }
        current.isEnd = true;
    }

    public boolean contains(String item) {
        TrieNode current = root;
        for (char c : item.toCharArray()) {
            int index = binarySearch(current.children, c);
            if (index < 0) {
                return false;
            }
            current = current.children[index];
        }
        return current.isEnd;
    }

    private int binarySearch(TrieNode[] children, char c) {
        int low = 0;
        int high = children.length - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (children[mid].data == c) {
                return mid;
            } else if (children[mid].data < c) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -low - 1;
    }

    private TrieNode[] insert(TrieNode[] array, TrieNode element, int index) {
        TrieNode[] newArray = new TrieNode[array.length + 1];
        System.arraycopy(array, 0, newArray, 0, index);
        newArray[index] = element;
        System.arraycopy(array, index, newArray, index + 1, array.length - index);
        return newArray;
    }
}

