class EggDropSolver {
    public static int solveEggDrop(int k, int n) {
        if (k <= 0 || n < 0) {
            return 0;
        }
        if (n == 0) {
            return 0;
        }
        if (k == 1) {
            return n;
        }
        if (n == 1) {
            return 1;
        }
        int[][] dp = new int[k + 1][n + 1];
        for (int i = 1; i <= k; i++) {
            dp[i][0] = 0;
            dp[i][1] = 1;
        }
        for (int j = 1; j <= n; j++) {
            dp[1][j] = j;
        }
        for (int i = 2; i <= k; i++) {
            for (int j = 2; j <= n; j++) {
                int low = 1;
                int high = j;
                int minAttempts = Integer.MAX_VALUE;
                while (low <= high) {
                    int mid = low + (high - low) / 2;
                    int broken = dp[i - 1][mid - 1];
                    int notBroken = dp[i][j - mid];
                    if (broken < notBroken) {
                        low = mid + 1;
                        minAttempts = Math.min(minAttempts, notBroken + 1);
                    } else if (broken > notBroken) {
                        high = mid - 1;
                        minAttempts = Math.min(minAttempts, broken + 1);
                    } else {
                        minAttempts = broken + 1;
                        break;
                    }
                }
                dp[i][j] = minAttempts;
            }
        }
        return dp[k][n];
    }
}

