                "DP Result: %s (Time: %s ns)%nMath Result: %s (Time: %s ns)%nMemo Result: %s (Time: %s ns)",
                formatter.format(dpResult),
                formatter.format(dpTime),
                formatter.format(mathResult),
                formatter.format(mathTime),
                formatter.format(memoResult),
                formatter.format(memoTime)
            );
        }
    }

    public static int solveEggDropDP(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }
        if (k == 1) return n;
        if (n == 1) return 1;

        int[][] dp = new int[k + 1][n + 1];
        for (int i = 1; i <= k; i++) {
            dp[i][0] = 0;
            dp[i][1] = 1;
        }
        for (int j = 1; j <= n; j++) {
            dp[1][j] = j;
        }
        for (极 i = 2; i <= k; i++) {
            for (int j = 2; j <= n; j++) {
                int low = 1;
                int high = j;
                int minAttempts = Integer.MAX_VALUE;
                while (low <= high) {
                    int mid = low + (high - low) / 2;
                    int broken = dp[i - 1][mid - 1];
                    int notBroken = dp[i][j - mid];
                    if (broken < notBroken) {
                        low = mid + 1;
                        minAttempts = Math.min(minAttempts, notBroken + 1);
                    } else if (broken > notBroken) {
                        high = mid - 1;
                        minAttempts = Math.min(minAttempts, broken + 1);
                    } else {
                        minAttempts = broken + 1;
                        break;
                    }
                }
                dp[i][j] = minAttempts;
            }
        }
        return dp[k][n];
    }

    public static int solveEggDropMath(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }
        if (k == 1) return n;
        if (n == 1) return 1;

        int m = 0;
        long sum = 0;
        while (sum < n) {
            m++;
            sum = 0;
            long term = 1;
            for (int i = 1; i <= k; i++) {
                term = term * (m - i + 1) / i;
                sum += term;
                if (sum >= n) break;
            }
        }
        return m;
    }

    private static int solveEggDropMemo(int k, int n, Map<String, Integer> memo) {
        if (k == 1) return n;
        if (n == 0) return 0;
        if (n == 1) return 1;

        String key = k + "," + n;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int low = 1;
        int high = n;
        int minAttempts = Integer.MAX_VALUE;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int broken = solveEggDropMemo(k - 1, mid - 1, memo);
            int notBroken = solveEggDropMemo(k, n - mid, memo);

            if (broken < notBroken) {
                low = mid + 1;
                minAttempts = Math.min(minAttempts, notBroken + 1);
            } else if (broken > notBroken) {
                high = mid - 1;
                minAttempts = Math.min(minAttempts, broken + 1);
            } else {
                minAttempts = broken + 1;
                break;
            }
        }

        memo.put(key, minAttempts);
        return minAttempts;
    }

    public static int solveEggDropMemo(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }
        Map<String, Integer> memo = new HashMap<>();
        return solveEggDropMemo(k, n, memo);
    }

    public static EggDropResult compareMethods(int k, int n) {
        long startTime = System.nanoTime();
        int dpResult = solveEggDropDP(k, n);
        long dpTime = System.nanoTime() - startTime;

        startTime = System.nanoTime();
        int mathResult = solveEggDropMath(k, n);
        long mathTime = System.nanoTime() - startTime;

        startTime = System.nanoTime();
        int memoResult = solveEggDropMemo(k, n);
        long memoTime = System.nanoTime() - startTime;

        return new EggDropResult(dpResult, dpTime, mathResult, mathTime, memoResult, memoTime);
    }
}
