class AdvancedFlagProcessor {
    private final Set<String> validFlags;

    public AdvancedFlagProcessor(Set<String> validFlags) {
        this.validFlags = new HashSet<>(validFlags);
    }

    public Set<String> processFlags(String flagString) {
        Set<String> result = new HashSet<>();
        if (flagString == null) {
            flagString = "";
        }
        String trimmed = flagString.trim();
        if (trimmed.isEmpty()) {
            for (String flag : validFlags) {
                result.add("|" + flag);
            }
            return result;
        }

        if (!trimmed.startsWith("|")) {
            return result;
        }

        while (trimmed.endsWith("|")) {
            trimmed = trimmed.substring(0, trimmed.length() - 1);
        }

        if (trimmed.isEmpty()) {
            for (String flag : validFlags) {
                result.add("|" + flag);
            }
            return result;
        }

        String[] parts = trimmed.split("\\|");
        Set<String> existingFlags = new HashSet<>();
        for (int i = 1; i < parts.length; i++) {
            String flag = parts[i];
            if (!validFlags.contains(flag)) {
                return result;
            }
            existingFlags.add(flag);
        }

        for (String flag : validFlags) {
            if (!existingFlags.contains(flag)) {
                result.add(trimmed + "|" + flag);
            }
        }

        return result;
    }
}

