import java.util.function.Consumer;
import java.util.function.Predicate;

public class EnhancedTestUtils {
    public static <T, E extends Throwable> Consumer<T> enhancedExceptionExpectation(
            Class<E> expectedExceptionClass, 
            Predicate<E> validator, 
            Consumer<T> operation) {

        return (T input) -> {
            try {
                operation.accept(input);
                throw new AssertionError("Expected exception of type " + 
                    expectedExceptionClass.getSimpleName() + 
                    " but no exception was thrown.");
            } catch (Throwable actualException) {
                if (!expectedExceptionClass.isInstance(actualException)) {
                    throw new AssertionError("Expected exception of type " + 
                        expectedExceptionClass.getSimpleName() + 
                        " but got " + 
                        actualException.getClass().getSimpleName() + 
                        " instead.");
                }

                E expectedException = expectedExceptionClass.cast(actualException);
                if (validator != null && !validator.test(expectedException)) {
                    throw new AssertionError("Thrown exception of type " + 
                        expectedExceptionClass.getSimpleName() + 
                        " failed validation.");
                }
            }
        };
    }
}

