import java.util.Comparator;

class EnhancedMergeSort {

    public Integer[] sortIntegers(Integer[] array) {
        if (array == null) {
            throw new IllegalArgumentException("Array must not be null");
        }
        if (array.length <= 1) {
            return array;
        }
        Integer[] result = array.clone();
        mergeSort(result, 0, result.length - 1, Comparator.naturalOrder(), true);
        return result;
    }

    public <T> T[] sort(T[] array, Comparator<? super T> comparator, boolean ascending) {
        if (array == null) {
            throw new IllegalArgumentException("Array must not be null");
        }
        if (comparator == null) {
            throw new IllegalArgumentException("Comparator must not be null");
        }
        if (array.length <= 1) {
            return array;
        }
        T[] result = array.clone();
        mergeSort(result, 0, result.length - 1, comparator, ascending);
        return result;
    }

    private <T> void mergeSort(T[] array, int left, int right, Comparator<? super T> comparator, boolean ascending) {
        if (left < right) {
            int mid = left + (right - left) / 2;
            mergeSort(array, left, mid, comparator, ascending);
            mergeSort(array, mid + 1, right, comparator, ascending);
            merge(array, left, mid, right, comparator, ascending);
        }
    }

    private <T> void merge(T[] array, int left, int mid, int right, Comparator<? super T> comparator, boolean ascending) {
        int n1 = mid - left + 1;
        int n2 = right - mid;

        @SuppressWarnings("unchecked")
        T[] leftArray = (T[]) new Object[n1];
        @SuppressWarnings("unchecked")
        T[] rightArray = (T[]) new Object[n2];

        System.arraycopy(array, left, leftArray, 0, n1);
        System.arraycopy(array, mid + 1, rightArray, 0, n2);

        int i = 0, j = 0, k = left;
        while (i < n1 && j < n2) {
            int comparison = comparator.compare(leftArray[i], rightArray[j]);
            if (ascending ? comparison <= 0 : comparison >= 0) {
                array[k] = leftArray[i];
                i++;
            } else {
                array[k] = rightArray[j];
                j++;
            }
            k++;
        }

        while (i < n1) {
            array[k] = leftArray[i];
            i++;
            k++;
        }

        while (j < n2) {
            array[k] = rightArray[j];
            j++;
            k++;
        }
    }
}

