    public <T> T[] sort(T[] array, Comparator<? super T> comparator, boolean ascending) {
        if (array == null) {
            throw new IllegalArgumentException("Array must not be null");
        }
        if (comparator == null) {
            throw new IllegalArgumentException("Comparator must not be null");
        }
        if (array.length <= 1) {
            return array;
        }
        T[] result = array.clone();
        mergeSort(result, 0, result.length - 1, comparator, ascending);
        return result;
    }

    private <T> void mergeSort(T[] array, int left, int right, Comparator<? super T> comparator, boolean ascending) {
        if (left < right) {
            int mid = left + (right - left) / 2;
            mergeSort(array, left, mid, comparator, ascending);
            mergeSort(array, mid + 1, right, comparator, ascending);

            // Create temporary arrays for left and right halves
            int n1 = mid - left + 1;
            int n2 = right - mid;

            @SuppressWarnings("unchecked")
            T[] leftArray = (T[]) new Object[n1];
            @SuppressWarnings("unchecked")
            T[] rightArray = (T[]) new Object[n2];

            System.arraycopy(array, left, leftArray, 0, n1);
            System.arraycopy(array, mid + 1, rightArray, 0, n2);

            // Merge the temporary arrays back into the original array
            merge(leftArray, rightArray, array, left, comparator, ascending);
        }
    }

    private <T> void merge(T[] leftArray, T[] rightArray, T[] targetArray, 
                          int targetStart, Comparator<? super T> comparator, boolean ascending) {
        int i = 0, j = 0, k = targetStart;

        while (i < leftArray.length && j < rightArray.length) {
            int comparison = comparator.compare(leftArray[i], rightArray[j]);
            if (ascending ? comparison <= 0 : comparison >= 0) {
                targetArray[k] = leftArray[i];
                i++;
            } else {
                targetArray[k] = rightArray[j];
                j++;
            }
            k++;
        }

        // Copy remaining elements from leftArray
        while (i < leftArray.length) {
            targetArray[k] = leftArray[i];
            i++;
            k++;
        }

        // Copy remaining elements from rightArray
        while (j < rightArray.length) {
