import java.util.ArrayList;
import java.util.List;

class SubsetGenerator {
    public List<List<Integer>> generateSubsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> lastIndices = new ArrayList<>();

        // Start with empty subset (last index -1)
        result.add(new ArrayList<>());
        lastIndices.add(-1);

        for (int i = 0; i < nums.length; i++) {
            int currentSize = result.size();
            for (int j = 0; j < currentSize; j++) {
                int lastIndex = lastIndices.get(j);
                // Only add to subsets that end before current position and have size < 2
                if (lastIndex < i && result.get(j).size() < 2) {
                    List<Integer> newSubset = new ArrayList<>(result.get(j));
                    newSubset.add(nums[i]);
                    result.add(newSubset);
                    lastIndices.add(i); // Update last index for the new subset
                }
            }
        }

        return result;
    }
}

