import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

class SecurePaymentProcessor {
    private static final char[] HEX_TABLE = "0123456789ABCDEF".toCharArray();

    public String generateSecurePaymentUrl(String baseUrl, Map<String, String> parameters, String secret) {
        // Input validation
        if (baseUrl == null || baseUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("baseUrl must not be null or empty");
        }
        if (secret == null || secret.trim().isEmpty()) {
            throw new IllegalArgumentException("secret must not be null or empty");
        }

        String secureHash = generateSecureHash(secret, parameters);

        if (parameters == null || parameters.isEmpty()) {
            return baseUrl;
        }

        List<String> sortedKeys = new ArrayList<>(parameters.keySet());
        Collections.sort(sortedKeys);

        StringBuilder queryString = new StringBuilder();
        for (String key : sortedKeys) {
            String value = parameters.get(key);
            try {
                String encodedKey = URLEncoder.encode(key, "UTF-8");
                String encodedValue = URLEncoder.encode(value, "UTF-8");
                if (queryString.length() > 0) {
                    queryString.append("&");
                }
                queryString.append(encodedKey).append("=").append(encodedValue);
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException("UTF-8 encoding not supported", e);
            }
        }

        String separator = baseUrl.contains("?") ? "&" : "?";
        return baseUrl + separator + queryString.toString();
    }

    private String generateSecureHash(String secret, Map<String, String> parameters) {
        try {
            StringBuilder dataBuilder = new StringBuilder();
            dataBuilder.append(secret);

            List<String> sortedKeys = new ArrayList<>(parameters.keySet());
            Collections.sort(sortedKeys);

            for (String key : sortedKeys) {
                String value = parameters.get(key);
                if (value != null && !value.isEmpty()) {
                    dataBuilder.append(value);
                }
            }

            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(dataBuilder.toString().getBytes("UTF-8"));

            return bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
            throw new RuntimeException("Error generating secure hash", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hexBuilder = new StringBuilder();
        for (byte b : bytes) {
            int val = b & 0xFF;
            hexBuilder.append(HEX_TABLE[val >>> 4]);
            hexBuilder.append(HEX_TABLE[val & 0x0F]);
        }
        return hexBuilder.toString();
    }
}

