import java.util.HashMap;
import java.util.Map;

public class AlertingService {
    private Map<String, Integer> alertCounts;
    private Map<String, String> lastAlertMessages;
    private Map<String, Map<String, AlertListener>> alertListeners;

    public interface AlertListener {
        void onAlert(String message);
    }

    public AlertingService() {
        alertCounts = new HashMap<>();
        lastAlertMessages = new HashMap<>();
        alertListeners = new HashMap<>();
    }

    public void triggerAlert(String severity, String message) {
        alertCounts.put(severity, alertCounts.getOrDefault(severity, 0) + 1);
        lastAlertMessages.put(severity, message);

        // Notify all listeners for this severity level
        if (alertListeners.containsKey(severity)) {
            for (AlertListener listener : alertListeners.get(severity).values()) {
                listener.onAlert(message);
            }
        }
    }

    public int getAlertCount(String severity) {
        return alertCounts.getOrDefault(severity, 0);
    }

    public String getLastAlertMessage(String severity) {
        return lastAlertMessages.get(severity);
    }

    public void resetStatistics() {
        alertCounts.clear();
        lastAlertMessages.clear();
    }

    public void addAlertListener(String listenerId, String severity, AlertListener callback) {
        alertListeners.putIfAbsent(severity, new HashMap<>());
        alertListeners.get(severity).put(listenerId, callback);
    }
}

