        ConcurrentMap<String, AlertListener> listeners = alertListeners.get(severity);
        if (listeners != null) {
            for (AlertListener listener : listeners.values()) {
                listener.onAlert(message);
            }
        }

        // Initialize with default values for consistency if this severity was encountered for the first time
        // alertCounts is already initialized above
        // lastAlertMessages is initialized by the put operation above
        // alertListeners doesn't need initialization here as it's handled in addAlertListener
    }

    public int getAlertCount(String severity) {
        AtomicInteger count = alertCounts.get(severity);
        return count != null ? count.get() : 0;
    }

    public String getLastAlertMessage(String severity) {
        return lastAlertMessages.get(severity);
    }

    public void resetStatistics() {
        alertCounts.clear();
        lastAlertMessages.clear();
    }

    public void addAlertListener(String listenerId, String severity, AlertListener callback) {
        // Ensure the alert level is initialized with default values
        alertCounts.computeIfAbsent(severity, k -> new AtomicInteger(0));

        // Initialize the listener map for this severity if needed
        ConcurrentMap<String, AlertListener> listeners = alertListeners.computeIfAbsent(
            severity, k -> new ConcurrentHashMap<>());

        // Register the callback
        listeners.put(listenerId, callback);
    }

    public void removeAlertListener(String listenerId, String severity) {
        ConcurrentMap<String, AlertListener> listeners = alertListeners.get(severity);
        if (listeners != null) {
            listeners.remove(listenerId);

            // Clean up empty severity entries
            if (listeners.isEmpty()) {
                alertListeners.remove(severity);
            }
        }
    }
}
