import java.util.ArrayList;
import java.util.List;

class TaskManager {
    private List<String> tasks;
    private String filename;

    public TaskManager(String filename) {
        this.filename = filename;
        this.tasks = new ArrayList<>();
    }

    public boolean addTask(String taskDescription) {
        if (taskDescription == null || taskDescription.trim().isEmpty()) {
            return false;
        }
        int taskNumber = tasks.size() + 1;
        tasks.add(taskNumber + ". " + taskDescription.trim());
        return true;
    }

    public boolean deleteTask(String position) {
        if (position == null) {
            return false;
        }

        if (position.equals("-1")) {
            tasks.clear();
            return true;
        }

        try {
            int index = Integer.parseInt(position) - 1;
            if (index < 0 || index >= tasks.size()) {
                return false;
            }

            tasks.remove(index);

            // Renumber remaining tasks
            for (int i = index; i < tasks.size(); i++) {
                String currentTask = tasks.get(i);
                int dotIndex = currentTask.indexOf(". ");
                if (dotIndex != -1) {
                    String description = currentTask.substring(dotIndex + 2);
                    tasks.set(i, (i + 1) + ". " + description);
                }
            }
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public List<String> getTasks() {
        return new ArrayList<>(tasks);
    }

    public int getTaskCount() {
        return tasks.size();
    }
}

