import java.util.List;
import java.util.ArrayList;

class PatternGenerator {
    public static List<String> generateSandClock(int size, boolean reverse, boolean useLetters) {
        if (size <= 0) {
            throw new IllegalArgumentException("Size must be positive");
        }

        int totalLines = 2 * size - 1;
        List<String> result = new ArrayList<>(totalLines);
        int totalWidth = 2 * size - 1;

        for (int i = 0; i < totalLines; i++) {
            int elements;
            if (i < size) {
                elements = size - i;
            } else {
                elements = i - size + 2;
            }

            StringBuilder sequence = new StringBuilder();
            for (int j = 1; j <= elements; j++) {
                if (useLetters) {
                    sequence.append((char) ('A' + j - 1));
                } else {
                    sequence.append(j);
                }
                if (j < elements) {
                    sequence.append(' ');
                }
            }

            int sequenceLength = sequence.length();
            int padding = (totalWidth - sequenceLength) / 2;
            StringBuilder line = new StringBuilder();
            for (int p = 0; p < padding; p++) {
                line.append(' ');
            }
            line.append(sequence);
            for (int p = 0; p < padding; p++) {
                line.append(' ');
            }
            result.add(line.toString());
        }

        if (reverse) {
            List<String> reversed = new ArrayList<>(result.size());
            for (int i = result.size() - 1; i >= 0; i--) {
                reversed.add(result.get(i));
            }
            return reversed;
        }

        return result;
    }
}

