import java.util.HashMap;
import java.util.Map;
import java.util.Stack;

public class BracketValidator {
    public static Map<String, Object> validateBrackets(String input) {
        Map<String, Object> result = new HashMap<>();
        Stack<Character> stack = new Stack<>();
        Map<Character, Character> bracketPairs = new HashMap<>();
        bracketPairs.put(')', '(');
        bracketPairs.put(']', '[');
        bracketPairs.put('}', '{');

        for (char ch : input.toCharArray()) {
            if (ch == '(' || ch == '[' || ch == '{') {
                stack.push(ch);
            } else if (bracketPairs.containsKey(ch)) {
                if (stack.isEmpty() || stack.pop() != bracketPairs.get(ch)) {
                    result.put("balanced", false);
                    return result;
                }
            }
        }

        result.put("balanced", stack.isEmpty());
        return result;
    }
}

