import java.util.HashMap;
import java.util.Map;
import java.util.Stack;

public class BracketValidator {
    public static Map<String, Object> validateBrackets(String input) {
        Map<String, Object> result = new HashMap<>();
        Stack<BracketInfo> stack = new Stack<>();
        Map<Character, Character> bracketPairs = new HashMap<>();
        bracketPairs.put(')', '(');
        bracketPairs.put(']', '[');
        bracketPairs.put('}', '{');

        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (ch == '(' || ch == '[' || ch == '{') {
                stack.push(new BracketInfo(ch, i));
            } else if (bracketPairs.containsKey(ch)) {
                if (stack.isEmpty()) {
                    result.put("balanced", false);
                    result.put("errorPosition", i);
                    result.put("errorType", "mismatch");
                    return result;
                }
                BracketInfo top = stack.pop();
                if (top.bracket != bracketPairs.get(ch)) {
                    result.put("balanced", false);
                    result.put("errorPosition", i);
                    result.put("errorType", "mismatch");
                    return result;
                }
            }
        }

        if (!stack.isEmpty()) {
            BracketInfo firstUnclosed = stack.firstElement();
            result.put("balanced", false);
            result.put("errorPosition", firstUnclosed.position);
            result.put("errorType", "unclosed");
            return result;
        }

        result.put("balanced", true);
        result.put("errorPosition", -1);
        result.put("errorType", "");
        return result;
    }

    private static class BracketInfo {
        char bracket;
        int position;

        BracketInfo(char bracket, int position) {
            this.bracket = bracket;
            this.position = position;
        }
    }
}

