public class ClassAnalyzer {
    public static String analyzeClass(String className) {
        StringBuilder report = new StringBuilder();
        try {
            Class<?> clazz = Class.forName(className);
            report.append("Class: ").append(clazz.getName()).append("\n\n");

            // Public Constructors section
            Constructor<?>[] publicConstructors = clazz.getConstructors();
            report.append("Public Constructors:\n");
            if (publicConstructors.length == 0) {
                report.append("  No public constructors\n");
            } else {
                for (Constructor<?> constructor : publicConstructors) {
                    report.append("  ").append(constructor.toString()).append("\n");
                }
            }

            report.append("\n");

            // Declared Constructors section
            Constructor<?>[] declaredConstructors = clazz.getDeclaredConstructors();
            report.append("Declared Constructors:\n");
            if (declaredConstructors.length == 0) {
                report.append("  No declared constructors\n");
            } else {
                for (Constructor<?> constructor : declaredConstructors) {
                    report.append("  ").append(constructor.toString()).append("\n");
                }
            }

        } catch (ClassNotFoundException e) {
            report.append("Class not found: ").append(className);
        }
        return report.toString();
    }
}

