import java.util.*;
import java.util.function.Function;

class MessageProcessor {
    private final Set<String> processedMessageIds;
    private final Map<String, Function<String, String>> handlers;
    private final List<RoutingRule> routingRules;

    public MessageProcessor() {
        processedMessageIds = new HashSet<>();
        handlers = new HashMap<>();
        routingRules = new ArrayList<>();
    }

    public void addHandler(String handlerKey, Function<String, String> handler) {
        handlers.put(handlerKey, handler);
    }

    public void addRoutingRule(String pattern, String handlerKey) {
        routingRules.add(new RoutingRule(pattern, handlerKey));
    }

    public String findHandlerKey(String path) {
        for (RoutingRule rule : routingRules) {
            if (matchesPattern(rule.pattern, path)) {
                return rule.handlerKey;
            }
        }
        return null;
    }

    public String processMessage(String messageId, String messageType, String content) {
        if (processedMessageIds.contains(messageId)) {
            return "Message already processed";
        }
        processedMessageIds.add(messageId);

        String handlerKey = findHandlerKey(messageType);
        if (handlerKey == null) {
            return "No handler found for message type: " + messageType;
        }

        Function<String, String> handler = handlers.get(handlerKey);
        if (handler == null) {
            return "No handler found for handler key: " + handlerKey;
        }
        return handler.apply(content);
    }

    private boolean matchesPattern(String pattern, String path) {
        String[] patternParts = pattern.split("/");
        String[] pathParts = path.split("/");
        int patternIndex = 0;
        int pathIndex = 0;

        while (patternIndex < patternParts.length && pathIndex < pathParts.length) {
            String patternPart = patternParts[patternIndex];
            String pathPart = pathParts[pathIndex];

            if (patternPart.equals("#")) {
                // Wildcard matches one or more segments
                patternIndex++;
                if (patternIndex == patternParts.length) {
                    // Wildcard at end matches remaining path
                    return true;
                }
                // Try to find where the next pattern part matches
                while (pathIndex < pathParts.length) {
                    if (matchesPattern(
                        String.join("/", Arrays.copyOfRange(patternParts, patternIndex, patternParts.length)),
                        String.join("/", Arrays.copyOfRange(pathParts, pathIndex, pathParts.length))
                    )) {
                        return true;
                    }
                    pathIndex++;
                }
                return false;
            } else if (patternPart.equals(pathPart)) {
                patternIndex++;
                pathIndex++;
            } else {
                return false;
            }
        }

        return patternIndex == patternParts.length && pathIndex == pathParts.length;
    }

    private static class RoutingRule {
        String pattern;
        String handlerKey;

        RoutingRule(String pattern, String handlerKey) {
            this.pattern = pattern;
            this.handlerKey = handlerKey;
        }
    }
