        if (handlerKey == null) {
            return "No handler found for message type: " + messageType;
        }

        Function<String, String> handler = handlers.get(handlerKey);
        if (handler == null) {
            return "No handler found for handler key: " + handlerKey;
        }
        return handler.apply(content);
    }

    private String matchPattern(String pattern, String path) {
        String[] patternParts = pattern.split("/");
        String[] pathParts = path.split("/");

        if (patternParts.length == 0 && pathParts.length == 0) {
            return routingRules.stream()
                .filter(rule -> rule.pattern.equals(pattern))
                .findFirst()
                .map(rule -> rule.handlerKey)
                .orElse(null);
        }

        int patternIndex = 0;
        int pathIndex = 0;

        while (patternIndex < patternParts.length && pathIndex < pathParts.length) {
            String patternPart = patternParts[patternIndex];
            String pathPart = pathParts[pathIndex];

            if (patternPart.equals("#")) {
                // '#' matches any sequence of characters (including dots)
                patternIndex++;
                if (patternIndex == patternParts.length) {
                    // Last pattern part is '#', matches remaining path
                    return routingRules.stream()
                        .filter(rule -> rule.pattern.equals(pattern))
                        .findFirst()
                        .map(rule -> rule.handlerKey)
                        .orElse(null);
                }
                // Try to match remaining pattern with remaining path
                while (pathIndex < pathParts.length) {
                    String remainingPattern = String.join("/", 
                        Arrays.copyOfRange(patternParts, patternIndex, patternParts.length));
                    String remainingPath = String.join("/", 
                        Arrays.copyOfRange(pathParts, pathIndex, pathParts.length));
                    String result = matchPattern(remainingPattern, remainingPath);
                    if (result != null) {
                        return result;
                    }
                    pathIndex++;
                }
                return null;
            } else if (patternPart.equals("*")) {
                // '*' matches any sequence of non-dot characters within a segment
                if (pathPart.contains(".")) {
                    return null;
                }
                patternIndex++;
                pathIndex++;
            } else if (patternPart.equals(pathPart)) {
                patternIndex++;
                pathIndex++;
            } else {
                return null;
            }
        }

        if (patternIndex == patternParts.length && pathIndex == pathParts.length) {
            return routingRules.stream()
                .filter(rule -> rule.pattern.equals(pattern))
                .findFirst()
                .map(rule -> rule.handlerKey)
                .orElse(null);
        }

        return null;
    }

    private static class RoutingRule {
        String pattern;
        String handlerKey;

        RoutingRule(String pattern, String handlerKey) {
            this.pattern = pattern;
            this.handlerKey = handlerKey;
        }
    }
