import java.util.concurrent.*;

public class ThreadExecutor {
    public static <T> T executeTaskWithTimeout(Callable<T> task, long timeout) throws TimeoutException, Exception {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<T> future = executor.submit(task);
        try {
            return future.get(timeout, TimeUnit.MILLISECONDS);
        } catch (TimeoutException e) {
            future.cancel(true); 
            throw e;
        } catch (ExecutionException e) {
            Throwable cause = e.getCause();
            if (cause instanceof Exception) {
                throw (Exception) cause;
            } else {
                throw new Exception(cause);
            }
        } catch (InterruptedException e) {
            future.cancel(true);
            throw e;
        } finally {
            executor.shutdown();
        }
    }
}

class SampleTask implements Callable<String> {
    private String name;
    private long sleepTime;

    public SampleTask(String name, long sleepTime) {
        this.name = name;
        this.sleepTime = sleepTime;
    }

    @Override
    public String call() throws Exception {
        System.out.println("Task " + name + " started");
        Thread.sleep(sleepTime);
        return "Result from " + name + " after " + sleepTime + "ms";
    }
}

