import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.List;

public class EnhancedFileOperations {
    public static class FileStats {
        public final int lineCount;
        public final int wordCount;
        public final int characterCount;
        public final double averageWordsPerLine;

        public FileStats(int lineCount, int wordCount, int characterCount, double averageWordsPerLine) {
            this.lineCount = lineCount;
            this.wordCount = wordCount;
            this.characterCount = characterCount;
            this.averageWordsPerLine = averageWordsPerLine;
        }

        @Override
        public String toString() {
            return String.format(
                "Line count: %d, Word count: %d, Character count: %d, Average words per line: %.2f",
                lineCount, wordCount, characterCount, averageWordsPerLine
            );
        }
    }

    private static List<String> readFileWithValidation(File file) throws IOException {
        if (file == null) {
            throw new IllegalArgumentException("File cannot be null");
        }
        if (!file.exists()) {
            throw new IOException("File does not exist: " + file.getPath());
        }
        if (!file.canRead()) {
            throw new IOException("Cannot read file: " + file.getPath());
        }

        return Files.readAllLines(file.toPath());
    }

    public static FileStats analyzeFileContent(File file) throws IOException {
        List<String> lines = readFileWithValidation(file);

        int lineCount = lines.size();
        int characterCount = 0;
        int wordCount = 0;

        for (String line : lines) {
            characterCount += line.length();
            // Split line by whitespace and count non-empty words
            String[] words = line.split("\\s+");
            for (String word : words) {
                if (!word.isEmpty()) {
                    wordCount++;
                }
            }
        }

        double averageWordsPerLine = (lineCount == 0) ? 0.0 : (double) wordCount / lineCount;

        return new FileStats(lineCount, wordCount, characterCount, averageWordsPerLine);
    }
}

