import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

class RegexHelper {
    public Map<String, String> generateRegexPattern(String patternType, Map<String, String> parameters) {
        Map<String, String> result = new HashMap<>();
        String pattern;
        String description;

        try {
            if ("literal".equals(patternType)) {
                String text = parameters.get("text");
                if (text != null) {
                    pattern = escapeRegexChars(text);
                    description = "Literal text";
                    result.put("pattern", pattern);
                    result.put("type", "literal");
                    result.put("description", description);
                }
            } else if ("characterClass".equals(patternType)) {
                String charClass = parameters.get("class");

                if ("digit".equals(charClass)) {
                    pattern = "\\d";
                    description = "Digit character";
                } else if ("lowercase".equals(charClass)) {
                    pattern = "[a-z]";
                    description = "Lowercase letter";
                } else if ("uppercase".equals(charClass)) {
                    pattern = "[A-Z]";
                    description = "Uppercase letter";
                } else {
                    pattern = ".";
                    description = "Any character";
                }

                result.put("pattern", pattern);
                result.put("type", "characterClass");
                result.put("description", description);
            } else if ("boundary".equals(patternType)) {
                String boundaryType = parameters.get("type");

                switch (boundaryType) {
                    case "start-line":
                        pattern = "^";
                        description = "Start of line";
                        break;
                    case "end-line":
                        pattern = "$";
                        description = "End of line";
                        break;
                    case "word":
                        pattern = "\\b";
                        description = "Word boundary";
                        break;
                    case "non-word":
                        pattern = "\\B";
                        description = "Non-word boundary";
                        break;
                    default:
                        throw new IllegalArgumentException("Unknown boundary type: " + boundaryType);
                }

                result.put("pattern", pattern);
                result.put("type", "boundary");
                result.put("description", description);
            } else if ("lookaround".equals(patternType)) {
                String lookaroundType = parameters.get("type");
                String innerPattern = parameters.get("pattern");

                if (innerPattern == null) {
                    throw new IllegalArgumentException("Missing 'pattern' parameter for lookaround");
                }

                switch (lookaroundType) {
                    case "ahead-positive":
                        pattern = "(?=" + innerPattern + ")";
                        description = "Positive lookahead";
                        break;
                    case "ahead-negative":
                        pattern = "(?!" + innerPattern + ")";
                        description = "Negative lookahead";
                        break;
                    case "behind-positive":
                        pattern = "(?<=" + innerPattern + ")";
                        description = "Positive lookbehind";
                        break;
                    case "behind-negative":
                        pattern = "(?<!" + innerPattern + ")";
                        description = "Negative lookbehind";
                        break;
                    default:
                        throw new IllegalArgumentException("Unknown lookaround type: " + lookaroundType);
                }

                result.put("pattern", pattern);
                result.put("type", "lookaround");
                result.put("description", description);
            } else if ("specialchar".equals(patternType)) {
                String specialType = parameters.get("type");

                switch (specialType) {
                    case "tab":
                        pattern = "\\t";
                        description = "Tab character";
                        break;
                    case "newline":
                        pattern = "\\n";
                        description = "Newline character";
                        break;
                    case "carriage-return":
                        pattern = "\\r";
                        description = "Carriage return";
                        break;
                    case "form-feed":
                        pattern = "\\f";
                        description = "Form feed";
                        break;
                    case "vertical-tab":
                        pattern = "\\x0B";
                        description = "Vertical tab";
                        break;
                    case "null":
                        pattern = "\\0";
                        description = "Null character";
                        break;
                    case "alert":
                        pattern = "\\a";
                        description = "Alert (bell)";
                        break;
                    case "escape":
                        pattern = "\\e";
                        description = "Escape character";
                        break;
                    default:
                        throw new IllegalArgumentException("Unknown special character type: " + specialType);
                }

                result.put("pattern", pattern);
                result.put("type", "specialchar");
                result.put("description", description);
            }

            // Validate the pattern if one was created
            if (result.containsKey("pattern")) {
                Pattern.compile(result.get("pattern"));
            }

        } catch (PatternSyntaxException e) {
            throw new PatternSyntaxException("Invalid regex pattern generated", result.get("pattern"), e.getIndex());
        }

        return result;
    }

    private String escapeRegexChars(String input) {
        return input.replaceAll("([.\\[\\]{}()*+\\-?^$|\\\\])", "\\\\$1");
    }
}

