import java.util.ArrayList;
import java.util.List;

public class CelestialSimulator {
    public static class Vector {
        public double x;
        public double y;

        public Vector(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    public static class Celestial {
        public String name;
        public double mass;
        public Vector position;
        public Vector velocity;
        public Vector acceleration;

        public Celestial(String name, double mass, Vector position, Vector velocity, Vector acceleration) {
            this.name = name;
            this.mass = mass;
            this.position = position;
            this.velocity = velocity;
            this.acceleration = acceleration;
        }
    }

    public static List<List<Celestial>> simulate(List<Celestial> bodies, double timeStep, int steps) {
        List<List<Celestial>> history = new ArrayList<>();
        history.add(deepCopy(bodies));

        for (int step = 0; step < steps; step++) {
            // Calculate accelerations
            for (Celestial body : bodies) {
                body.acceleration = new Vector(0, 0);
                for (Celestial other : bodies) {
                    if (body == other) continue;
                    double dx = other.position.x - body.position.x;
                    double dy = other.position.y - body.position.y;
                    double rSquared = dx * dx + dy * dy;
                    double force = 6.67430e-11 * body.mass * other.mass / rSquared;
                    double angle = Math.atan2(dy, dx);
                    body.acceleration.x += force * Math.cos(angle) / body.mass;
                    body.acceleration.y += force * Math.sin(angle) / body.mass;
                }
            }

            // Update velocities and positions
            for (Celestial body : bodies) {
                body.velocity.x += body.acceleration.x * timeStep;
                body.velocity.y += body.acceleration.y * timeStep;
                body.position.x += body.velocity.x * timeStep;
                body.position.y += body.velocity.y * timeStep;
            }

            history.add(deepCopy(bodies));
        }

        return history;
    }

    private static List<Celestial> deepCopy(List<Celestial> bodies) {
        List<Celestial> copy = new ArrayList<>();
        for (Celestial body : bodies) {
            copy.add(new Celestial(
                body.name,
                body.mass,
                new Vector(body.position.x, body.position.y),
                new Vector(body.velocity.x, body.velocity.y),
                new Vector(body.acceleration.x, body.acceleration.y)
            ));
        }
        return copy;
    }
}

