import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

class ThreadSynchronizer {
    private final ReentrantLock lock;
    private final Condition condition;
    private boolean isSignalled;

    public ThreadSynchronizer() {
        lock = new ReentrantLock();
        condition = lock.newCondition();
        isSignalled = false;
    }

    public boolean waitWithDeadline(int waitSeconds) {
        boolean wasSignalled = false;
        lock.lock();
        try {
            long deadlineMillis = System.currentTimeMillis() + TimeUnit.SECONDS.toMillis(waitSeconds);
            Date deadline = new Date(deadlineMillis);

            // Loop to handle spurious wakeups
            while (!isSignalled) {
                if (!condition.awaitUntil(deadline)) {
                    // Timeout reached
                    return false;
                }
            }
            wasSignalled = true;
            return true;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } finally {
            if (wasSignalled) {
                isSignalled = false;
            }
            lock.unlock();
        }
    }

    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
}

