import java.util.Date;
import java.util.HashMap;
import java.util.Map;

class AuthTokenValidator {
    private Map<String, TokenInfo> tokenDatabase;
    private Map<String, User> userDatabase;

    // Inner classes for TokenInfo and User
    static class TokenInfo {
        String userId;
        Date expiration;
        int status;

        TokenInfo(String userId, Date expiration, int status) {
            this.userId = userId;
            this.expiration = expiration;
            this.status = status;
        }
    }

    static class User {
        String id;
        String name;

        User(String id, String name) {
            this.id = id;
            this.name = name;
        }
    }

    public AuthTokenValidator() {
        tokenDatabase = new HashMap<>();
        userDatabase = new HashMap<>();

        // Create expiration date (1 hour from now)
        long oneHour = 3600 * 1000; // milliseconds in an hour
        Date expiration = new Date(System.currentTimeMillis() + oneHour);

        // Initialize with sample data
        String sampleToken = "token_user_123";
        String userId = "user123";

        // Add token with status 1 (active) and future expiration
        tokenDatabase.put(sampleToken, new TokenInfo(userId, expiration, 1));

        // Add user
        userDatabase.put(userId, new User(userId, "John Doe"));
    }

    public Map<String, Object> validateToken(String token, String clientIp) {
        Map<String, Object> result = new HashMap<>();

        if (token == null || token.isEmpty()) {
            result.put("valid", false);
            result.put("message", "Token is empty");
            return result;
        }

        if (!token.contains("user")) {
            result.put("valid", false);
            result.put("message", "Token format invalid");
            return result;
        }

        int index = token.indexOf("user");
        String extractedIp = token.substring(index + 4);
        if (!extractedIp.equals(clientIp)) {
            result.put("valid", false);
            result.put("message", "IP address mismatch");
            return result;
        }

        if (!tokenDatabase.containsKey(token)) {
            result.put("valid", false);
            result.put("message", "Token not found");
            return result;
        }

        TokenInfo tokenInfo = tokenDatabase.get(token);

        // Check expiration
        if (tokenInfo.expiration.before(new Date())) {
            result.put("valid", false);
            result.put("message", "Token expired");
            return result;
        }

        // Check status
        if (tokenInfo.status != 1) {
            result.put("valid", false);
            result.put("message", "Token invalid");
            return result;
        }

        // Check if user exists
        if (!userDatabase.containsKey(tokenInfo.userId)) {
            result.put("valid", false);
            result.put("message", "User not found");
            return result;
        }

        // All checks passed
        result.put("valid", true);
        result.put("message", "Validation successful");
        result.put("user", userDatabase.get(tokenInfo.userId));
        return result;
    }
}

