import java.util.ArrayList;
import java.util.List;

class AdvancedBST {
    private Node root;

    private class Node {
        int value;
        Node left, right;

        Node(int value) {
            this.value = value;
            left = right = null;
        }
    }

    public void insert(int value) {
        root = insertRec(root, value);
    }

    private Node insertRec(Node root, int value) {
        if (root == null) {
            return new Node(value);
        }
        if (value < root.value) {
            root.left = insertRec(root.left, value);
        } else if (value > root.value) {
            root.right = insertRec(root.right, value);
        }
        return root;
    }

    public void remove(int value) {
        root = removeRec(root, value);
    }

    private Node removeRec(Node root, int value) {
        if (root == null) {
            return null;
        }

        if (value < root.value) {
            root.left = removeRec(root.left, value);
        } else if (value > root.value) {
            root.right = removeRec(root.right, value);
        } else {
            // Node found - handle different cases
            if (root.left == null && root.right == null) {
                // Case 1: No children
                return null;
            } else if (root.left == null) {
                // Case 2: One child (right)
                return root.right;
            } else if (root.right == null) {
                // Case 3: One child (left)
                return root.left;
            } else {
                // Case 4: Two children
                // Find the smallest value in the right subtree (in-order successor)
                Node successor = findMin(root.right);
                // Replace the current node's value with the successor's value
                root.value = successor.value;
                // Remove the successor from the right subtree
                root.right = removeRec(root.right, successor.value);
            }
        }
        return root;
