import java.util.*;

public class TreePathAnalyzer {
    private List<Node> diameter = new ArrayList<>();

    public static class Node {
        int data;
        List<Node> children = new ArrayList<>();

        public Node(int data) {
            this.data = data;
        }

        public void addChild(Node child) {
            children.add(child);
        }
    }

    public List<Node> findLongestPath(Node root) {
        dfs(root);
        return diameter;
    }

    private List<Node> dfs(Node node) {
        if (node == null) {
            return new ArrayList<>();
        }

        List<List<Node>> childPaths = new ArrayList<>();
        for (Node child : node.children) {
            childPaths.add(dfs(child));
        }

        childPaths.sort((a, b) -> Integer.compare(b.size(), a.size()));

        List<Node> longestPathFromNode = new ArrayList<>();
        longestPathFromNode.add(node);
        if (!childPaths.isEmpty()) {
            longestPathFromNode.addAll(childPaths.get(0));
        }

        if (longestPathFromNode.size() > diameter.size()) {
            diameter = new ArrayList<>(longestPathFromNode);
        }

        if (childPaths.size() >= 2) {
            List<Node> firstPath = childPaths.get(0);
            List<Node> secondPath = childPaths.get(1);
            List<Node> reversedFirstPath = new ArrayList<>(firstPath);
            Collections.reverse(reversedFirstPath);

            List<Node> candidate = new ArrayList<>();
            candidate.addAll(reversedFirstPath);
            candidate.add(node);
            candidate.addAll(secondPath);

            if (candidate.size() > diameter.size()) {
                diameter = candidate;
            }
        }

        return longestPathFromNode;
    }
}

