import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.function.Supplier;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return executeWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries);
    }

    private <T> CompletableFuture<T> executeWithRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int retriesLeft) {

        CompletableFuture<T> future = new CompletableFuture<>();

        CompletableFuture.supplyAsync(taskSupplier)
            .orTimeout(timeout, timeUnit)
            .whenComplete((result, throwable) -> {
                if (throwable == null) {
                    future.complete(result);
                } else {
                    if (retriesLeft > 0) {
                        new Thread(() -> {
                            try {
                                Thread.sleep(500);
                                executeWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, retriesLeft - 1)
                                    .whenComplete((retryResult, retryThrowable) -> {
                                        if (retryThrowable != null) {
                                            future.completeExceptionally(retryThrowable);
                                        } else {
                                            future.complete(retryResult);
                                        }
                                    });
                            } catch (InterruptedException e) {
                                future.completeExceptionally(e);
                            }
                        }).start();
                    } else {
                        if (throwable instanceof TimeoutException) {
                            future.complete(fallbackValue);
                        } else {
                            future.completeExceptionally(throwable);
                        }
                    }
                }
            });

        return future;
    }
}

