import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.function.Supplier;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        CompletableFuture<T> resultFuture = new CompletableFuture<>();
        executeWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, resultFuture, 
                        null, 0);
        return resultFuture;
    }

    private <T> void executeWithRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int retriesLeft,
            CompletableFuture<T> resultFuture,
            Throwable lastException,
            int attemptCount) {

        CompletableFuture.supplyAsync(taskSupplier)
            .orTimeout(timeout, timeUnit)
            .whenComplete((result, throwable) -> {
                if (throwable == null) {
                    resultFuture.complete(result);
                } else {
                    Throwable currentException = throwable.getCause() instanceof TimeoutException ? 
                                               throwable.getCause() : throwable;

                    if (retriesLeft > 0) {
                        try {
                            Thread.sleep(500);
                            executeWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, 
                                            retriesLeft - 1, resultFuture, 
                                            currentException instanceof TimeoutException ? 
                                                lastException : currentException, 
                                            attemptCount + 1);
                        } catch (InterruptedException e) {
                            resultFuture.completeExceptionally(e);
                        }
                    } else {
                        if (currentException instanceof TimeoutException) {
                            resultFuture.complete(fallbackValue);
                        } else {
                            resultFuture.completeExceptionally(
                                lastException != null ? lastException : currentException);
                        }
                    }
                }
            });
