import java.util.Map;
import java.util.LinkedHashMap;
import java.util.Collection;
import java.util.Iterator;
import java.lang.reflect.Array;
import org.json.JSONObject;
import org.json.JSONArray;
import org.json.JSONException;
import java.util.logging.Logger;

class DataStructureAnalyzer {
    private static final Logger logger = Logger.getLogger(DataStructureAnalyzer.class.getName());

    public static Map<String, Object> analyzeDataStructure(Object data) {
        if (data == null) {
            throw new IllegalArgumentException("Input data cannot be null");
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("containsBinary", false);
        result.put("maxDepth", 0);
        result.put("totalElements", 0);

        Map<String, Integer> typeCounts = new LinkedHashMap<>();
        typeCounts.put("JSONObject", 0);
        typeCounts.put("JSONArray", 0);
        typeCounts.put("String", 0);
        typeCounts.put("Number", 0);
        typeCounts.put("Boolean", 0);
        typeCounts.put("byte[]", 0);
        typeCounts.put("Other", 0);

        result.put("typeCounts", typeCounts);

        analyzeRecursive(data, result, typeCounts, 1);

        return result;
    }

    private static void analyzeRecursive(Object data, Map<String, Object> result, 
                                       Map<String, Integer> typeCounts, int currentDepth) {
        if (data == null) {
            return;
        }

        // Increment total elements for current node
        int total = (Integer) result.get("totalElements");
        result.put("totalElements", total + 1);

        // Update max depth if needed
        int currentMaxDepth = (Integer) result.get("maxDepth");
        if (currentDepth > currentMaxDepth) {
            result.put("maxDepth", currentDepth);
        }

        // Handle different data types
        if (data.getClass().isArray()) {
            handleArray(data, result, typeCounts, currentDepth);
        } else if (data instanceof Map) {
            handleMap((Map<?, ?>) data, result, typeCounts, currentDepth);
        } else if (data instanceof Collection) {
            handleCollection((Collection<?>) data, result, typeCounts, currentDepth);
        } else if (data instanceof JSONObject) {
            handleJSONObject((JSONObject) data, result, typeCounts, currentDepth);
        } else if (data instanceof JSONArray) {
            handleJSONArray((JSONArray) data, result, typeCounts, currentDepth);
        } else {
            handlePrimitive(data, result, typeCounts);
        }
    }

    private static void handleArray(Object array, Map<String, Object> result, 
                                  Map<String, Integer> typeCounts, int currentDepth) {
        Class<?> componentType = array.getClass().getComponentType();
        if (componentType == byte.class) {
            typeCounts.put("byte[]", typeCounts.get("byte[]") + 1);
            result.put("containsBinary", true);
        } else {
            typeCounts.put("JSONArray", typeCounts.get("JSONArray") + 1);
            int length = Array.getLength(array);
            for (int i = 0; i < length; i++) {
                Object element = Array.get(array, i);
                analyzeRecursive(element, result, typeCounts, currentDepth + 1);
            }
        }
    }

    private static void handleMap(Map<?, ?> map, Map<String, Object> result, 
                                Map<String, Integer> typeCounts, int currentDepth) {
        typeCounts.put("JSONObject", typeCounts.get("JSONObject") + 1);
        for (Object value : map.values()) {
            analyzeRecursive(value, result, typeCounts, currentDepth + 1);
        }
    }

    private static void handleCollection(Collection<?> collection, Map<String, Object> result, 
                                       Map<String, Integer> typeCounts, int currentDepth) {
        typeCounts.put("JSONArray", typeCounts.get("JSONArray") + 1);
        for (Object element : collection) {
            analyzeRecursive(element, result, typeCounts, currentDepth + 1);
        }
    }

    private static void handleJSONObject(JSONObject jsonObject, Map<String, Object> result, 
                                      Map<String, Integer> typeCounts, int currentDepth) {
        typeCounts.put("JSONObject", typeCounts.get("JSONObject") + 1);

        Iterator<String> keys = jsonObject.keys();
        while (keys.hasNext()) {
            String key = keys.next();
            try {
                Object value = jsonObject.get(key);
                if (value != null) {
                    analyzeRecursive(value, result, typeCounts, currentDepth + 1);
                }
            } catch (JSONException e) {
                logger.warning("Failed to access value for key '" + key + "' in JSONObject: " + e.getMessage());
            }
        }
    }

    private static void handleJSONArray(JSONArray jsonArray, Map<String, Object> result, 
                                     Map<String, Integer> typeCounts, int currentDepth) {
        typeCounts.put("JSONArray", typeCounts.get("JSONArray") + 1);

        int length = jsonArray.length();
        for (int i = 0; i < length; i++) {
            try {
                Object element = jsonArray.get(i);
                if (element != null) {
                    analyzeRecursive(element, result, typeCounts, currentDepth + 1);
                }
            } catch (JSONException e) {
                logger.warning("Failed to access element at index " + i + " in JSONArray: " + e.getMessage());
            }
        }
    }

    private static void handlePrimitive(Object data, Map<String, Object> result, 
                                      Map<String, Integer> typeCounts) {
        if (data instanceof String) {
            typeCounts.put("String", typeCounts.get("String") + 1);
        } else if (data instanceof Number) {
            typeCounts.put("Number", typeCounts.get("Number") + 1);
        } else if (data instanceof Boolean) {
            typeCounts.put("Boolean", typeCounts.get("Boolean") + 1);
        } else {
            typeCounts.put("Other", typeCounts.get("Other") + 1);
        }
    }
}
