import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.ArrayList;
import java.util.List;

public class EnhancedMessageProcessor {
    private final Map<String, Integer> destinationCountMap = new HashMap<>();
    private final Map<String, Message> latestMessageMap = new HashMap<>();
    private final Map<String, List<Message>> destinationMessagesMap = new HashMap<>();
    private int totalMessages = 0;

    public synchronized ProcessingResult postMessage(Message message, String destination) {
        // Update destination count
        destinationCountMap.put(destination, destinationCountMap.getOrDefault(destination, 0) + 1);

        // Store as latest message for this destination
        latestMessageMap.put(destination, message);

        // Store message in destination-specific list
        if (!destinationMessagesMap.containsKey(destination)) {
            destinationMessagesMap.put(destination, new ArrayList<>());
        }
        destinationMessagesMap.get(destination).add(message);

        // Update total message count
        totalMessages++;

        // Create metadata with total message count
        Map<String, Object> metadata = new HashMap<>();
        metadata.put("totalMessages", totalMessages);

        return new ProcessingResult(Status.SUCCESS, metadata);
    }

    public synchronized Message getMessage(String destination) {
        return latestMessageMap.get(destination);
    }

    public synchronized Map<String, Message> getMessagesByType(String contentType) {
        Map<String, Message> result = new LinkedHashMap<>();
        for (Map.Entry<String, List<Message>> entry : destinationMessagesMap.entrySet()) {
            String destination = entry.getKey();
            List<Message> messages = entry.getValue();
            for (Message message : messages) {
                if (message.getContentType().equals(contentType)) {
                    // Preserve insertion order by adding in the order found
                    result.putIfAbsent(destination, message);
                }
            }
        }
        return result;
    }

    public synchronized ProcessingResult clearMessages(String destination) {
        if (!destinationMessagesMap.containsKey(destination)) {
            return new ProcessingResult(Status.NOT_FOUND, null);
        }

        // Remove all messages for this destination
        int removedCount = destinationMessagesMap.get(destination).size();
        destinationMessagesMap.remove(destination);
        latestMessageMap.remove(destination);
        destinationCountMap.remove(destination);
        totalMessages -= removedCount;

        Map<String, Object> metadata = new HashMap<>();
        metadata.put("removedCount", removedCount);
        metadata.put("totalMessages", totalMessages);

        return new ProcessingResult(Status.SUCCESS, metadata);
    }

    public synchronized int getDestinationCount(String destination) {
        return destinationCountMap.getOrDefault(destination, 0);
    }

    public synchronized int getTotalMessages() {
        return totalMessages;
    }
}

