        String inputHash = hashPassword(password);
        if (storedHash.equals(inputHash)) {
            return new AuthenticationResult(true, "Authentication successful");
        } else {
            return new AuthenticationResult(false, "Invalid password");
        }
    }

    public RegistrationResult registerUser(String username, String password) {
        if (username == null || username.isEmpty()) {
            return new RegistrationResult(false, "Username cannot be null or empty");
        }

        if (password == null || password.isEmpty()) {
            return new RegistrationResult(false, "Password cannot be null or empty");
        }

        PasswordValidator validator = new PasswordValidator();
        ValidationResult validationResult = validator.validate(password);

        if (!validationResult.isValid()) {
            return new RegistrationResult(false, validationResult.getMessage());
        }

        if (userCredentials.containsKey(username)) {
            return new RegistrationResult(false, "Username already exists");
        }

        userCredentials.put(username, hashPassword(password));
        return new RegistrationResult(true, "Registration successful");
    }

    private String hashPassword(String password) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(password.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not found", e);
        }
    }
}
