    private double availableBandwidth;

    public Channel(String name, double availableBandwidth) {
        if (name == null) {
            throw new NullPointerException("Channel name must not be null");
        }
        if (availableBandwidth <= 0) {
            throw new IllegalArgumentException("Bandwidth must be positive");
        }
        this.name = name;
        this.availableBandwidth = availableBandwidth;
    }

    public String getName() {
        return name;
    }

    public double getAvailableBandwidth() {
        return availableBandwidth;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Channel channel = (Channel) o;
        return Double.compare(channel.availableBandwidth, availableBandwidth) == 0 &&
                Objects.equals(name, channel.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, availableBandwidth);
    }
}

public class Plan {
    private FrequencyAssignment[] frequencyAssignments;
    private Channel[] channels;

    public Plan(FrequencyAssignment[] frequencyAssignments, Channel[] channels) {
        this.frequencyAssignments = frequencyAssignments;
        this.channels = channels;
    }

    public double getTotalRequiredBandwidth() {
        double total = 0.0;
        for (FrequencyAssignment assignment : frequencyAssignments) {
            total += assignment.getRequiredBandwidth();
        }
        return total;
    }

    public double getTotalAvailableBandwidth() {
        double total = 0.0;
        for (Channel channel : channels) {
            total += channel.getAvailableBandwidth();
        }
        return total;
    }

    public boolean isFeasible() {
        return getTotalAvailableBandwidth() >= getTotalRequiredBandwidth();
    }

    public Channel findChannelWithMaxBandwidth() {
        if (channels == null || channels.length == 0) {
            return null;
        }

        Channel maxBandwidthChannel = channels[0];
        for (int i = 1; i < channels.length; i++) {
            if (channels[i].getAvailableBandwidth() > maxBandwidthChannel.getAvailableBandwidth()) {
                maxBandwidthChannel = channels[i];
            }
        }
        return maxBandwidthChannel;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Plan plan = (Plan) o;
        return Arrays.equals(frequencyAssignments, plan.frequencyAssignments) &&
                Arrays.equals(channels, plan.channels);
    }

    @Override
    public int hashCode() {
        int result = Arrays.hashCode(frequencyAssignments);
        result = 31 * result + Arrays.hashCode(channels);
        return result;
    }

    public static Plan createPlan(double[] requiredBandwidths, double[] availableBandwidths) {
        int validRequiredCount = 0;
        for (double bandwidth : requiredBandwidths) {
            if (bandwidth > 0) validRequiredCount++;
        }

        int validAvailableCount = 0;
        for (double bandwidth : availableBandwidths) {
            if (bandwidth > 0) validAvailableCount++;
        }

        FrequencyAssignment[] assignments = new FrequencyAssignment[validRequiredCount];
        Channel[] channels = new Channel[validAvailableCount];

        int reqIndex = 0;
        for (double bandwidth : requiredBandwidths) {
            if (bandwidth > 0) {
                try {
                    assignments[reqIndex] = new FrequencyAssignment(
                        new Channel("AssignmentChannel" + (reqIndex + 1), 1.0), 
                        bandwidth
                    );
                    reqIndex++;
                } catch (IllegalArgumentException | NullPointerException e) {
                    // Skip invalid assignment
                }
            }
        }

        int avlIndex = 0;
        for (double bandwidth : availableBandwidths) {
            if (bandwidth > 0) {
                try {
                    channels[avlIndex] = new Channel("Channel" + (avlIndex + 1), bandwidth);
                    avlIndex++;
                } catch (IllegalArgumentException | NullPointerException e) {
                    // Skip invalid channel
                }
            }
        }

        return new Plan(assignments, channels);
    }
}

