class NeuralNetworkCalculator {
    private final int inputSize;
    private final int hiddenSize;
    private final int outputSize;
    private final double[] weights;
    private final double[][] inputNormalizationParams;
    private final double[][] outputNormalizationParams;

    public NeuralNetworkCalculator(int inputSize, int hiddenSize, int outputSize, 
                                 double[] weights, double[][] inputNormParams, 
                                 double[][] outputNormParams) {
        this.inputSize = inputSize;
        this.hiddenSize = hiddenSize;
        this.outputSize = outputSize;
        this.weights = weights;
        this.inputNormalizationParams = inputNormParams;
        this.outputNormalizationParams = outputNormParams;
    }

    public double[] calculate(double[] input) {
        // Normalize input
        double[] normalizedInput = new double[inputSize];
        for (int i = 0; i < inputSize; i++) {
            normalizedInput[i] = (input[i] - inputNormalizationParams[i][0]) / inputNormalizationParams[i][1];
        }

        // Extract weights and biases
        int idx = 0;
        double[][] w1 = new double[hiddenSize][inputSize];
        for (int i = 0; i < hiddenSize; i++) {
            for (int j = 0; j < inputSize; j++) {
                w1[i][j] = weights[idx++];
            }
        }

        double[] b1 = new double[hiddenSize];
        for (int i = 0; i < hiddenSize; i++) {
            b1[i] = weights[idx++];
        }

        double[][] w2 = new double[outputSize][hiddenSize];
        for (int i = 0; i < outputSize; i++) {
            for (int j = 0; j < hiddenSize; j++) {
                w2[i][j] = weights[idx++];
            }
        }

        double[] b2 = new double[outputSize];
        for (int i = 0; i < outputSize; i++) {
            b2[i] = weights[idx];
            idx++;
        }

        // Hidden layer computation with ReLU
        double[] hidden = new double[hiddenSize];
        for (int i = 0; i < hiddenSize; i++) {
            double sum = b1[i];
            for (int j = 0; j < inputSize; j++) {
                sum += w1[i][j] * normalizedInput[j];
            }
            hidden[i] = Math.max(0, sum); // ReLU activation
        }

        // Output layer computation (linear activation)
        double[] output = new double[outputSize];
        for (int i = 0; i < outputSize; i++) {
            double sum = b2[i];
            for (int j = 0; j < hiddenSize; j++) {
                sum += w2[i][j] * hidden[j];
            }
            output[i] = sum;
        }

        // Denormalize output
        double[] denormalizedOutput = new double[outputSize];
        for (int i = 0; i < outputSize; i++) {
            denormalizedOutput[i] = output[i] * outputNormalizationParams[i][1] + outputNormalizationParams[i][0];
        }

        return denormalizedOutput;
    }
}

