    public static class ThreadStatistics {
        private int totalTasks;
        private int completedTasks;
        private int interruptedTasks;

        public ThreadStatistics(int totalTasks, int completedTasks, int interruptedTasks) {
            this.totalTasks = totalTasks;
            this.completedTasks = completedTasks;
            this.interruptedTasks = interruptedTasks;
        }

        public int getTotalTasks() { return totalTasks; }
        public int getCompletedTasks() { return completedTasks; }
        public int getInterruptedTasks() { return interruptedTasks; }
    }

    public ThreadStatistics manageThreads(int threadCount, long workDurationMs, long interruptAfterMs) throws InterruptedException {
        Thread[] threads = new Thread[threadCount];
        AtomicInteger completedTasks = new AtomicInteger(0);
        AtomicInteger interruptedTasks = new AtomicInteger(0);
        AtomicBoolean isInterrupted = new AtomicBoolean(false);
        CountDownLatch latch = new CountDownLatch(threadCount);

        Runnable workerTask = () -> {
            System.out.println("Thread " + Thread.currentThread().getName() + " started");
            try {
                Thread.sleep(workDurationMs);
                if (!isInterrupted.get()) {
                    completedTasks.incrementAndGet();
                }
            } catch (InterruptedException e) {
                interruptedTasks.incrementAndGet();
                System.out.println("Thread " + Thread.currentThread().getName() + " was interrupted");
            } finally {
                latch.countDown();
            }
        };

        for (int i = 0; i < threadCount; i++) {
            threads[i] = new Thread(workerTask);
            threads[i].start();
        }

        // Create and start the interrupter thread
        Thread interrupterThread = new Thread(() -> {
            try {
                Thread.sleep(interruptAfterMs);
                isInterrupted.set(true);

                // Interrupt all alive worker threads
                for (Thread thread : threads) {
                    if (thread.isAlive()) {
                        thread.interrupt();
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        interrupterThread.start();

        // Wait for all worker threads to complete
        latch.await();

        return new ThreadStatistics(threadCount, completedTasks.get(), interruptedTasks.get());
    }
}

