import java.util.*;

public class State {
    private String name;
    private boolean isFinal;

    public State(String name, boolean isFinal) {
        this.name = name;
        this.isFinal = isFinal;
    }

    public String getName() {
        return name;
    }

    public boolean isFinal() {
        return isFinal;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        State state = (State) o;
        return Objects.equals(name, state.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name);
    }
}

public class DFA {
    private List<State> states;
    private State initialState;
    private Map<State, Map<Character, State>> transitions;
    private boolean hasInitialState = false;
    private Set<State> finalStates;

    public DFA() {
        states = new ArrayList<>();
        transitions = new HashMap<>();
        finalStates = new HashSet<>();
    }

    public void addState(State state) {
        if (!hasInitialState) {
            initialState = state;
            hasInitialState = true;
        }
        transitions.putIfAbsent(state, new HashMap<>());
        if (state.isFinal()) {
            finalStates.add(state);
        }
        states.add(state);
    }

    public void addTransition(State from, char input, State to) {
        if (!transitions.containsKey(from)) {
            throw new IllegalArgumentException("From state not added to DFA");
        }
        if (!transitions.containsKey(to)) {
            throw new IllegalArgumentException("To state not added to DFA");
        }
        transitions.get(from).put(input, to);
    }

    public boolean accepts(String input) {
        State current = initialState;
        for (char c : input.toCharArray()) {
            Map<Character, State> stateTransitions = transitions.get(current);
            if (stateTransitions == null || !stateTransitions.containsKey(c)) {
                return false;
            }
            current = stateTransitions.get(c);
        }
        return finalStates.contains(current);
    }
}

