import java.util.*;

class State {
    private String name;
    private boolean isFinal;
    private Map<Character, State> transitions;

    public State(String name, boolean isFinal) {
        this.name = name;
        this.isFinal = isFinal;
        this.transitions = new HashMap<>();
    }

    public String getName() {
        return name;
    }

    public boolean isFinal() {
        return isFinal;
    }

    public void addTransition(char input, State nextState) {
        transitions.put(input, nextState);
    }

    public State getNextState(char input) {
        return transitions.get(input);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append(name);
        sb.append(": ");
        for (Map.Entry<Character, State> entry : transitions.entrySet()) {
            sb.append("--");
            sb.append(entry.getKey());
            sb.append("-> ");
            sb.append(entry.getValue().getName());
            sb.append(" ");
        }
        return sb.toString().trim();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        State state = (State) o;
        return Objects.equals(name, state.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name);
    }
}

class DFA {
    private List<State> states;
    private State initialState;
    private boolean hasInitialState = false;
    private Set<State> finalStates;
    private Set<Character> alphabet;

    public DFA() {
        states = new ArrayList<>();
        finalStates = new HashSet<>();
        alphabet = new HashSet<>();
    }

    public void addState(State state) {
        if (!hasInitialState) {
            initialState = state;
            hasInitialState = true;
        }
        if (state.isFinal()) {
            finalStates.add(state);
        }
        states.add(state);
    }

    public void addTransition(State from, char input, State to) {
        if (!states.contains(from)) {
            throw new IllegalArgumentException("From state not added to DFA");
        }
        if (!states.contains(to)) {
            throw new IllegalArgumentException("To state not added to DFA");
        }
        from.addTransition(input, to);
        alphabet.add(input);
    }

    public boolean accepts(String input) {
        State current = initialState;
        for (char c : input.toCharArray()) {
            State next = current.getNextState(c);
            if (next == null) {
                return false;
            }
            current = next;
        }
        return current.isFinal();
    }

    public Set<Character> getAlphabet() {
        return alphabet;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Number of states: ").append(states.size()).append("\n");
        sb.append("Alphabet: ").append(alphabet).append("\n");
        sb.append("Initial state: ").append(initialState.getName()).append("\n");
        sb.append("Final states: ");
        for (State s : finalStates) {
            sb.append(s.getName()).append(" ");
        }
        sb.append("\n");
        sb.append("Transitions:\n");
        for (State state : states) {
            sb.append(state.toString()).append("\n");
