import java.util.*;

public class DataMatcher {
    private static final String DELIMITER = "___|||___";

    public Map<String, List<String[]>> enhancedMatch(List<String[]> dataset1, List<String[]> dataset2, int matchStrategy, int[] keyIndices) {
        Map<String, List<String[]>> result = new HashMap<>();
        result.put("matched", new ArrayList<>());
        result.put("unmatched1", new ArrayList<>());
        result.put("unmatched2", new ArrayList<>());

        if (matchStrategy != 1) {
            throw new UnsupportedOperationException("Only matchStrategy 1 is supported.");
        }

        Map<String, LinkedList<String[]>> map2 = new HashMap<>();
        for (String[] record : dataset2) {
            String key = buildKey(record, keyIndices);
            map2.computeIfAbsent(key, k -> new LinkedList<>()).add(record);
        }

        for (String[] record1 : dataset1) {
            String key = buildKey(record1, keyIndices);
            LinkedList<String[]> recordsList = map2.get(key);
            if (recordsList != null && !recordsList.isEmpty()) {
                String[] record2 = recordsList.removeFirst();
                String[] combined = concatenateArrays(record1, record2);
                result.get("matched").add(combined);
            } else {
                result.get("unmatched1").add(record1);
            }
        }

        for (LinkedList<String[]> records : map2.values()) {
            result.get("unmatched2").addAll(records);
        }

        return result;
    }

    private String buildKey(String[] record, int[] keyIndices) {
        String[] keyParts = new String[keyIndices.length];
        for (int i = 0; i < keyIndices.length; i++) {
            int index = keyIndices[i];
            keyParts[i] = record[index].trim();
        }
        return String.join(DELIMITER, keyParts);
    }

    private String[] concatenateArrays(String[] arr1, String[] arr2) {
        String[] combined = new String[arr1.length + arr2.length];
        System.arraycopy(arr1, 0, combined, 0, arr1.length);
        System.arraycopy(arr2, 0, combined, arr1.length, arr2.length);
        return combined;
    }
}

