import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

public class ServerApprovalHandler {
    private String serverName;
    private String serverIp;
    private String realmId;
    private String imageId;
    private String hardwareProfileId;
    private Map<String, String> approvalStatus;

    public ServerApprovalHandler(String serverName, String serverIp, String realmId, String imageId, String hardwareProfileId) {
        this.serverName = serverName;
        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
        this.approvalStatus.put("system", "pending");
        this.approvalStatus.put("network", "pending");
        this.approvalStatus.put("security", "pending");
    }

    public Map<String, Boolean> validateConfiguration() {
        Map<String, Boolean> validationResults = new HashMap<>();
        validationResults.put("serverNameValid", serverName != null && !serverName.trim().isEmpty());
        validationResults.put("serverIpValid", isValidIp(serverIp));
        validationResults.put("realmIdValid", realmId != null && !realmId.trim().isEmpty());
        validationResults.put("imageIdValid", imageId != null && !imageId.trim().isEmpty());
        validationResults.put("hardwareProfileIdValid", hardwareProfileId != null && !hardwareProfileId.trim().isEmpty());
        return validationResults;
    }

    public Map<String, Object> processApproval() {
        Map<String, Boolean> validationResults = validateConfiguration();
        boolean allValid = validationResults.values().stream().allMatch(Boolean::booleanValue);
        String message;

        if (allValid) {
            approvalStatus.replaceAll((k, v) -> "approved");
            message = "Configuration approved successfully";
        } else {
            approvalStatus.replaceAll((k, v) -> "rejected");
            message = "Configuration validation failed";
        }

        Map<String, Object> result = new HashMap<>();
        result.put("approvalStatus", approvalStatus);
        result.put("message", message);
        result.put("validationResults", validationResults);
        return result;
    }

    private boolean isValidIp(String ip) {
        if (ip == null || ip.trim().isEmpty()) {
            return false;
        }
        String ipRegex = "^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$";
        return Pattern.compile(ipRegex).matcher(ip).matches();
    }
}

