import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PaginationProcessor<T> {
    private List<T> dataset;
    private int defaultPageSize;

    public PaginationProcessor(List<T> dataset, int defaultPageSize) {
        this.dataset = new ArrayList<>(dataset);
        this.defaultPageSize = defaultPageSize;
    }

    public PaginationResult<T> getPaginatedData(int pageNumber, int itemsPerPage) {
        if (itemsPerPage <= 0) {
            throw new IllegalArgumentException("itemsPerPage must be greater than 0");
        }
        if (pageNumber < 1) {
            throw new IllegalArgumentException("pageNumber must be greater than or equal to 1");
        }

        int totalItems = dataset.size();
        int totalPages = (int) Math.ceil((double) totalItems / itemsPerPage);

        if (totalItems == 0) {
            return new PaginationResult<>(Collections.emptyList(), pageNumber, itemsPerPage, totalPages, totalItems);
        }

        int adjustedPage = Math.min(pageNumber, totalPages);
        int startIndex = (adjustedPage - 1) * itemsPerPage;
        int endIndex = Math.min(startIndex + itemsPerPage, totalItems);

        if (startIndex >= totalItems) {
            return new PaginationResult<>(Collections.emptyList(), adjustedPage, itemsPerPage, totalPages, totalItems);
        }

        List<T> pageData = dataset.subList(startIndex, endIndex);
        return new PaginationResult<>(pageData, adjustedPage, itemsPerPage, totalPages, totalItems);
    }

    public static class PaginationResult<T> {
        private final List<T> data;
        private final int currentPage;
        private final int itemsPerPage;
        private final int totalPages;
        private final int totalItems;

        public PaginationResult(List<T> data, int currentPage, int itemsPerPage, int totalPages, int totalItems) {
            this.data = new ArrayList<>(data);
            this.currentPage = currentPage;
            this.itemsPerPage = itemsPerPage;
            this.totalPages = totalPages;
            this.totalItems = totalItems;
        }

        public List<T> getData() {
            return data;
        }

        public int getCurrentPage() {
            return currentPage;
        }

        public int getItemsPerPage() {
            return itemsPerPage;
        }

        public int getTotalPages() {
            return totalPages;
        }

        public int getTotalItems() {
            return totalItems;
        }
    }
}

