import java.util.*;
import java.util.stream.Collectors;

class ScenarioAnalyzer {
    public Map<String, Object> analyzeScenario(ScenarioNode root) {
        Map<String, Integer> nodeIndices = new HashMap<>();
        Queue<ScenarioNode> queue = new LinkedList<>();
        queue.add(root);
        int index = 0;

        while (!queue.isEmpty()) {
            ScenarioNode currentNode = queue.poll();
            nodeIndices.put(currentNode.getName(), index++);
            List<ScenarioNode> children = currentNode.getChildren();
            if (children != null) {
                queue.addAll(children.stream()
                    .filter(Objects::nonNull)
                    .collect(Collectors.toList()));
            }
        }

        return Map.of("nodeIndices", nodeIndices);
    }
}

