import java.util.*;
import java.util.stream.Collectors;

class ScenarioAnalyzer {
    public Map<String, Object> analyzeScenario(ScenarioNode root) {
        Map<String, Integer> nodeIndices = new HashMap<>();
        Map<Integer, Integer> syncPairs = new HashMap<>();
        Queue<ScenarioNode> queue = new LinkedList<>();
        Map<ScenarioNode, ScenarioNode> parentMap = new HashMap<>();

        queue.add(root);
        parentMap.put(root, null);
        int index = 0;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                ScenarioNode currentNode = queue.poll();
                nodeIndices.put(currentNode.getName(), index);

                List<ScenarioNode> children = currentNode.getChildren();
                if (children != null) {
                    for (ScenarioNode child : children) {
                        if (child != null) {
                            queue.add(child);
                            parentMap.put(child, currentNode);
                        }
                    }
                }

                if (currentNode.isSync()) {
                    ScenarioNode parent = parentMap.get(currentNode);
                    if (parent != null) {
                        String parentServerName = parent.getServerName();
                        if (children != null) {
                            for (ScenarioNode child : children) {
                                if (child != null && parentServerName.equals(child.getServerName())) {
                                    syncPairs.put(index, nodeIndices.get(child.getName()));
                                    break;
                                }
                            }
                        }
                    }
                }

                index++;
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("nodeIndices", nodeIndices);
        result.put("syncPairs", syncPairs);
        return result;
    }
}

