import java.util.HashMap;
import java.util.Map;
import java.util.ArrayList;
import java.util.List;

class AgricultureDataValidator {

    public Map<String, Object> validateAndProcessData(String ph, String humidity, String fertilizer, String temperature, String irrigation) {
        Map<String, Object> result = new HashMap<>();
        List<String> errors = new ArrayList<>();

        // Validate pH
        try {
            double phValue = Double.parseDouble(ph);
            if (phValue < 0 || phValue > 14) {
                errors.add("pH incorrecto, debe estar entre 0 y 14.");
            }
        } catch (NumberFormatException e) {
            errors.add("pH debe ser un número válido.");
        }

        // Validate humidity
        try {
            double humidityValue = Double.parseDouble(humidity);
            if (humidityValue < 0 || humidityValue > 100) {
                errors.add("Humedad incorrecta, debe estar entre 0 y 100.");
            }
        } catch (NumberFormatException e) {
            errors.add("Humedad debe ser un número válido.");
        }

        // Validate fertilizer
        try {
            double fertilizerValue = Double.parseDouble(fertilizer);
            if (fertilizerValue < 0 || fertilizerValue > 100) {
                errors.add("Abono incorrecto, debe estar entre 0 y 100.");
            }
        } catch (NumberFormatException e) {
            errors.add("Abono debe ser un número válido.");
        }

        // Validate temperature
        try {
            double temperatureValue = Double.parseDouble(temperature);
            if (temperatureValue < -50 || temperatureValue > 100) {
                errors.add("Temperatura fuera de rango (-50 a 100°C).");
            }
        } catch (NumberFormatException e) {
            errors.add("Temperatura debe ser un número válido.");
        }

        // Validate irrigation
        if (!irrigation.equalsIgnoreCase("ON") && !irrigation.equalsIgnoreCase("OFF")) {
            errors.add("Riego debe ser 'ON' u 'OFF'.");
        }

        if (!errors.isEmpty()) {
            result.put("isValid", false);
            result.put("errors", errors);
        } else {
            result.put("isValid", true);
            String processedData = "ph=" + ph + "&humedad=" + humidity + "&abono=" + fertilizer + 
                                  "&temperatura=" + temperature + "&riego=" + irrigation.toUpperCase();
            result.put("processedData", processedData);
        }

        return result;
    }
}

