    private Set<String> requiredKeys;

    public ConfigurationManager(Set<String> requiredKeys) {
        this.configMap = new HashMap<>();
        this.requiredKeys = requiredKeys;
    }

    public void loadConfiguration(Map<String, Object> properties) {
        Set<String> missingKeys = new java.util.HashSet<>(requiredKeys);
        missingKeys.removeAll(properties.keySet());

        if (!missingKeys.isEmpty()) {
            throw new ConfigurationException("Missing required configuration keys: " + missingKeys);
        }

        configMap.putAll(properties);
    }

    @SuppressWarnings("unchecked")
    public <T> T getConfigValue(String key, Class<T> type) {
        return (T) configMap.get(key);
    }
}

