import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.List;
import java.util.ArrayList;

interface Validator {
    void validate(Object value) throws ConfigurationException;
}

class ConfigurationException extends RuntimeException {
    public ConfigurationException(String message) {
        super(message);
    }
}

public class ConfigurationManager {
    private Map<String, Object> configMap;
    private Set<String> requiredKeys;
    private Map<String, List<Validator>> validators;

    public ConfigurationManager(Set<String> requiredKeys, Map<String, List<Validator>> validators) {
        this.configMap = new HashMap<>();
        this.requiredKeys = requiredKeys;
        this.validators = validators != null ? new HashMap<>(validators) : new HashMap<>();
    }

    public void loadConfiguration(Map<String, Object> properties) {
        Set<String> missingKeys = new java.util.HashSet<>(requiredKeys);
        missingKeys.removeAll(properties.keySet());

        if (!missingKeys.isEmpty()) {
            throw new ConfigurationException("Missing required configuration keys: " + missingKeys);
        }

        validateConfiguration(properties);
        configMap.putAll(properties);
    }

    private void validateConfiguration(Map<String, Object> properties) {
        for (Map.Entry<String, Object> entry : properties.entrySet()) {
            String key = entry.getKey();
