    private static final Long MOCK_ID = 1L;
    private static final String MOCK_ACCOUNT = "testuser";
    private static final String MOCK_EMAIL = "test@example.com";
    private static final String MOCK_PASSWORD = "password";

    // Thread-safe caches
    private static final ConcurrentHashMap<String, User> accountCache = new ConcurrentHashMap<>();
    private static final ConcurrentHashMap<String, User> emailCache = new ConcurrentHashMap<>();
    private static final ConcurrentHashMap<Long, User> idCache = new ConcurrentHashMap<>();

    private User findUserInDatabase(Object identifier, String password) {
        // Simulate database lookup with mock data
        if (identifier instanceof String) {
            String stringIdentifier = (String) identifier;
            boolean isEmail = stringIdentifier.contains("@");

            if ((isEmail && stringIdentifier.equals(MOCK_EMAIL) && password.equals(MOCK_PASSWORD)) ||
                (!isEmail && stringIdentifier.equals(MOCK_ACCOUNT) && password.equals(MOCK_PASSWORD))) {
                return new User(MOCK_ID, MOCK_ACCOUNT, MOCK_EMAIL);
            }
        } else if (identifier instanceof Long) {
            Long longIdentifier = (Long) identifier;

            if (longIdentifier.equals(MOCK_ID) && password.equals(MOCK_PASSWORD)) {
                return new User(MOCK_ID, MOCK_ACCOUNT, MOCK_EMAIL);
            }
        }
        return null;
    }

    private void cacheUser(User user) {
        if (user != null) {
            accountCache.put(user.getAccountName(), user);
            emailCache.put(user.getEmail(), user);
            idCache.put(user.getId(), user);
        }
    }

    public Map<String, Object> authenticateUser(Object identifier, String password) {
        Map<String, Object> response = new HashMap<>();
        User cachedUser = null;

        // Check cache first
        if (identifier instanceof String) {
            String stringIdentifier = (String) identifier;
            boolean isEmail = stringIdentifier.contains("@");

            if (isEmail) {
                cachedUser = emailCache.get(stringIdentifier);
            } else {
                cachedUser = accountCache.get(stringIdentifier);
            }
        } else if (identifier instanceof Long) {
            cachedUser = idCache.get((Long) identifier);
        } else {
            throw new IllegalArgumentException("Identifier must be either String or Long");
        }

        // If user found in cache, validate password
        if (cachedUser != null) {
            if (password.equals(MOCK_PASSWORD)) {
                response.put("authenticated", true);
                response.put("user", cachedUser);
            } else {
                response.put("authenticated", false);
                response.put("message", "Invalid credentials");
            }
            return response;
        }

        // If not in cache, query database
        User user = findUserInDatabase(identifier, password);
        if (user != null) {
            cacheUser(user);
            response.put("authenticated", true);
            response.put("user", user);
        } else {
            response.put("authenticated", false);
            response.put("message", "Invalid credentials");
        }

        return response;
    }
}

