public class PlayerManagement {
    private final Map<String, PlayerInfo> players;
    private final ConcurrentLinkedQueue<String> playerQueue;

    public PlayerManagement() {
        players = new ConcurrentHashMap<>();
        playerQueue = new ConcurrentLinkedQueue<>();
    }

    public synchronized boolean registerPlayer(String playerId, int score) {
        if (players.containsKey(playerId)) {
            return false;
        }
        PlayerInfo newPlayer = new PlayerInfo(playerId, score);
        players.put(playerId, newPlayer);
        playerQueue.offer(playerId);
        return true;
    }

    public PlayerInfo getPlayer(String playerId) {
        PlayerInfo player = players.get(playerId);
        return (player != null && player.isActive()) ? player : null;
    }

    public synchronized boolean removePlayer(String playerId) {
        PlayerInfo player = players.get(playerId);
        if (player != null && player.isActive()) {
            player.setInactive();
            players.remove(playerId);
            playerQueue.remove(playerId);
            return true;
        }
        return false;
    }

    public synchronized boolean updateScore(String playerId, int points) {
        PlayerInfo player = players.get(playerId);
        if (player != null && player.isActive()) {
            player.updateScore(points);
            return true;
        }
        return false;
    }

    public synchronized PlayerInfo getNextPlayer() {
        if (playerQueue.isEmpty()) {
            return null;
        }

        String nextPlayerId = playerQueue.poll();
        PlayerInfo player = players.get(nextPlayerId);

        // Skip inactive players
        while (player != null && !player.isActive()) {
            nextPlayerId = playerQueue.poll();
            player = players.get(nextPlayerId);
            if (player == null) {
                break;
            }
        }

        // If we found an active player, add them back to the end of the queue
        if (player != null && player.isActive()) {
            playerQueue.offer(nextPlayerId);
            return player;
        }

        return null;
    }
}

