    public TileConfiguration calculateAdvancedTile(boolean[] neighbors) {
        // Assuming neighbors order: [UP, RIGHT, DOWN, LEFT]
        boolean up = neighbors[0];
        boolean right = neighbors[1];
        boolean down = neighbors[2];
        boolean left = neighbors[3];

        int count = countNeighbors(up, right, down, left);

        if (count == 0) {
            return new TileConfiguration(0, 0);
        } else if (count == 1) {
            // Single neighbor dead ends
            if (up) return new TileConfiguration(1, 0);
            if (down) return new TileConfiguration(0, 2);
            if (left) return new TileConfiguration(5, 1);
            if (right) return new TileConfiguration(5, 0);
        } else if (count == 2) {
            // Check for opposing pairs
            if (up && down && !left && !right) {
                return new TileConfiguration(5, 2); // Vertical passage
            }
            if (left && right && !up && !down) {
                return new TileConfiguration(1, 2); // Horizontal passage
            }
        }

        // All other configurations
        return new TileConfiguration(1, 1);
    }

    private int countNeighbors(boolean up, boolean right, boolean down, boolean left) {
        int count = 0;
        if (up) count++;
        if (right) count++;
        if (down) count++;
        if (left) count++;
        return count;
    }
}

