public class AdvancedTileCalculator {

    public static class TileConfiguration {
        private final int x;
        private final int y;

        public TileConfiguration(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    public TileConfiguration calculateAdvancedTile(boolean[] neighbors) {
        // Neighbor indices
        final int UP = 0;
        final int RIGHT = 1;
        final int DOWN = 2;
        final int LEFT = 3;
        final int UP_LEFT = 4;
        final int UP_RIGHT = 5;
        final int DOWN_LEFT = 6;
        final int DOWN_RIGHT = 7;

        // Extract neighbor values
        boolean up = neighbors[UP];
        boolean right = neighbors[RIGHT];
        boolean down = neighbors[DOWN];
        boolean left = neighbors[LEFT];
        boolean upLeft = neighbors[UP_LEFT];
        boolean upRight = neighbors[UP_RIGHT];
        boolean downLeft = neighbors[DOWN_LEFT];
        boolean downRight = neighbors[DOWN_RIGHT];

        // Cardinal neighbor count
        int cardinalCount = (up ? 1 : 0) + (right ? 1 : 0) + (down ? 1 : 0) + (left ? 1 : 0);

        // Diagonal neighbor count
        int diagonalCount = (upLeft ? 1 : 0) + (upRight ? 1 : 0) + (downLeft ? 1 : 0) + (downRight ? 1 : 0);

        // Total neighbor count
        int totalCount = cardinalCount + diagonalCount;

        // No neighbors
        if (totalCount == 0) {
            return new TileConfiguration(0, 0);
        }

        // Dead ends (single cardinal neighbor only)
        if (cardinalCount == 1 && diagonalCount == 0) {
            if (up) return new TileConfiguration(1, 0);
            if (down) return new TileConfiguration(0, 2);
            if (left) return new TileConfiguration(5, 1);
            if (right) return new TileConfiguration(5, 0);
        }

        // Passages (only opposing cardinals)
        if (cardinalCount == 2 && diagonalCount == 0) {
            if (up && down && !left && !right) return new TileConfiguration(5, 2);
            if (left && right && !up && !down) return new TileConfiguration(1, 2);
        }

        // Diagonal corners (specific combinations)
        if (up && left && upLeft && !right && !down && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(3, 0);
        }
        if (up && right && upRight && !left && !down && !upLeft && !downLeft && !downRight) {
