public class ListDivision {
    public static List<Integer> divideLists(List<Integer> list1, List<Integer> list2) {
        if (list1 == null || list2 == null) {
            throw new IllegalArgumentException("Input lists must not be null");
        }

        int minSize = Math.min(list1.size(), list2.size());
        List<Integer> result = new ArrayList<>(minSize);

        for (int i = 0; i < minSize; i++) {
            int divisor = list2.get(i);
            if (divisor == 0) {
                throw new ArithmeticException("Division by zero at index " + i);
            }
            result.add(list1.get(i) / divisor);
        }

        return result;
    }
}

