class UserManager {
    private Map<String, User> userDatabase;
    private Map<String, String> activeSessions;

    public UserManager() {
        this.userDatabase = new HashMap<>();
        this.activeSessions = new HashMap<>();
    }

    public boolean registerUser(String username, String password, String email) {
        if (userDatabase.containsKey(username)) {
            return false;
        }
        userDatabase.put(username, new User(username, password, email));
        return true;
    }

    public String loginUser(String username, String password) {
        User user = userDatabase.get(username);
        if (user != null && user.getPassword().equals(password)) {
            String token = UUID.randomUUID().toString();
            activeSessions.put(token, username);
            return token;
        }
        return null;
    }

    public boolean logoutUser(String username) {
        Iterator<Map.Entry<String, String>> iterator = activeSessions.entrySet().iterator();
        boolean found = false;
        while (iterator.hasNext()) {
            Map.Entry<String, String> entry = iterator.next();
            if (entry.getValue().equals(username)) {
                iterator.remove();
                found = true;
            }
        }
        return found;
    }

    public boolean isUserLoggedIn(String username) {
        return activeSessions.containsValue(username);
    }
