import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.List;
import java.io.File;
import java.io.IOException;

class FileHandler {
    public static String handleFileOperation(String operationType, List<File> files, String targetDirectory) {
        if ("upload".equals(operationType)) {
            int count = 0;
            try {
                Path targetPath = Paths.get(targetDirectory);
                if (!Files.exists(targetPath)) {
                    Files.createDirectories(targetPath);
                }

                for (File file : files) {
                    if (file.exists()) {
                        Path sourcePath = file.toPath();
                        Path destinationPath = targetPath.resolve(file.getName());
                        Files.copy(sourcePath, destinationPath, StandardCopyOption.REPLACE_EXISTING);
                        count++;
                    }
                }
                return String.format("Successfully uploaded %d files", count);
            } catch (IOException e) {
                return "Error during file operation: " + e.getMessage();
            }
        } else {
            return "Unsupported operation: " + operationType;
        }
    }
}

