                    }
                }
                return String.format("Successfully uploaded %d files", count);
            } catch (IOException e) {
                return "Error during file operation: " + e.getMessage();
            }
        } else if ("download".equals(operationType)) {
            try {
                Path filePath = Paths.get(targetDirectory, fileName);
                return Files.readAllBytes(filePath);
            } catch (IOException e) {
                throw new RuntimeException("Error reading file: " + fileName, e);
            }
        } else {
            return "Unsupported operation: " + operationType;
        }
