public class Factory {
    private int inputStock;
    private int outputStock;
    private int version;
    private int intermediateStock1;
    private int intermediateStock2;

    public Factory(int version, int initialInput) {
        this.version = version;
        this.inputStock = initialInput;
        this.outputStock = 0;
        this.intermediateStock1 = 0;
        this.intermediateStock2 = 0;
    }

    public int[] process(int itemsToProcess) {
        int processed = 0;
        switch (version) {
            case 1:
                processed = Math.min(inputStock, itemsToProcess);
                inputStock -= processed;
                outputStock += processed;
                break;
            case 2:
                while (processed < itemsToProcess && inputStock > 0) {
                    inputStock--;
                    processed++;
                    outputStock++;

                    if (processed < itemsToProcess && inputStock > 0) {
                        inputStock--;
                        processed++;
                        outputStock++;
                    }
                }
                break;
            case 3:
                while (processed < itemsToProcess && inputStock > 0) {
                    inputStock--;
                    intermediateStock1++;

                    if (intermediateStock1 > 0) {
                        intermediateStock1--;
                        processed++;
                        outputStock++;
                    }
                }
                break;
            case 4:
                while (processed < itemsToProcess && inputStock > 0) {
                    inputStock--;
                    intermediateStock1++;

                    if (inputStock > 0) {
                        inputStock--;
                        intermediateStock2++;
                    }

                    if (intermediateStock1 > 0 && intermediateStock2 > 0) {
                        intermediateStock1--;
                        intermediateStock2--;
                        processed++;
                        outputStock++;
                    }
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid factory version: " + version);
        }
        return new int[]{processed, inputStock};
    }
}

