import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.atomic.AtomicInteger;

public class Factory {
    private final int version;
    private final AtomicInteger inputStock;
    private final AtomicInteger outputStock;
    private AtomicInteger intermediateStock1;
    private AtomicInteger intermediateStock2;
    private final ReentrantLock lock;
    private final Condition inputAvailable;
    private final Condition intermediateAvailable;
    private final int itemsToProcess;
    private final AtomicInteger processedCount;
    private boolean productionComplete;

    public Factory(int version, int initialInput, int itemsToProcess) {
        this.version = version;
        this.inputStock = new AtomicInteger(initialInput);
        this.outputStock = new AtomicInteger(0);
        this.intermediateStock1 = new AtomicInteger(0);
        this.intermediateStock2 = new AtomicInteger(0);
        this.lock = new ReentrantLock();
        this.inputAvailable = lock.newCondition();
        this.intermediateAvailable = lock.newCondition();
        this.itemsToProcess = itemsToProcess;
        this.processedCount = new AtomicInteger(0);
        this.productionComplete = false;
    }

    public int[] process() throws InterruptedException {
        Thread[] workshops;

        switch (version) {
            case 1:
                workshops = new Thread[1];
                workshops[0] = new Thread(new WorkshopV1());
                break;
            case 2:
                workshops = new Thread[2];
                for (int i = 0; i < 2; i++) {
                    workshops[i] = new Thread(new WorkshopV2());
                }
                break;
            case 3:
                workshops = new Thread[2];
                workshops[0] = new Thread(new WorkshopV3A());
                workshops[1] = new Thread(new WorkshopV3B());
                break;
            case 4:
                workshops = new Thread[3];
                workshops[0] = new Thread(new WorkshopV4A());
                workshops[1] = new Thread(new WorkshopV4B());
                workshops[2] = new Thread(new WorkshopV4C());
                break;
            default:
                throw new IllegalArgumentException("Invalid factory version: " + version);
        }

        for (Thread workshop : workshops) {
            workshop.start();
        }

        for (Thread workshop : workshops) {
            workshop.join();
        }

        return new int[]{processedCount.get(), inputStock.get()};
    }

    private class WorkshopV1 implements Runnable {
        @Override
        public void run() {
            while (processedCount.get() < itemsToProcess) {
                lock.lock();
                try {
                    while (inputStock.get() == 0 && !productionComplete) {
                        inputAvailable.await();
                    }

                    if (productionComplete) break;

                    inputStock.decrementAndGet();
                    outputStock.incrementAndGet();
                    if (processedCount.incrementAndGet() >= itemsToProcess) {
                        productionComplete = true;
                        inputAvailable.signalAll();
                        intermediateAvailable.signalAll();
                        break;
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                } finally {
                    lock.unlock();
                }
            }
        }
    }

    private class WorkshopV2 implements Runnable {
        @Override
        public void run() {
            while (processedCount.get() < itemsToProcess) {
                lock.lock();
                try {
                    while (inputStock.get() == 0 && !productionComplete) {
